const COMBINED_QUESTIONS = [{"id":"ml-1","sourceBank":"microsoft-learn","type":"single","question":"What is the primary business value of Microsoft Power Apps?","options":["It provides a rapid low-code/no-code environment to build custom web and mobile business apps","It is a relational database engine","It is only used to create dashboards and reports","It hosts external-facing public websites"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Power Apps","sub":null,"explanation":"Power Apps provides a rapid low-code development environment for building custom apps (web and mobile) that meet business needs, so business users and professional developers alike can build apps without extensive coding.","source":{"title":"Explore Microsoft Power Platform (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/2-explore-microsoft-power-platform"}},{"id":"ml-2","sourceBank":"microsoft-learn","type":"single","question":"What does Microsoft Power Automate help organizations do?","options":["Build external websites","Create automated workflows between apps and services to automate repetitive business processes","Store relational data","Visualize data in dashboards"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Power Automate","sub":null,"explanation":"Power Automate lets users create automated workflows between applications and services, automating repetitive processes such as communication, data collection, and approvals — for users of all technical skill levels.","source":{"title":"Explore Microsoft Power Platform (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/2-explore-microsoft-power-platform"}},{"id":"ml-3","sourceBank":"microsoft-learn","type":"single","question":"Which Power Platform service is a low-code SaaS platform for creating secure, external-facing business websites?","options":["Power Apps","Power Automate","Power Pages","Dataverse"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Power Pages","sub":null,"explanation":"Power Pages is a secure, enterprise-grade, low-code SaaS platform for creating, hosting, and managing modern external-facing business websites, using the same Dataverse business data as other Power Platform components.","source":{"title":"Explore Microsoft Power Platform (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/2-explore-microsoft-power-platform"}},{"id":"ml-4","sourceBank":"microsoft-learn","type":"single","question":"What is the role of connectors in Power Platform?","options":["They store data in tables","They act as bridges that link apps, data, and services — with 1,400+ prebuilt connectors used by Power Apps and Power Automate","They are used only to build websites","They replace the need for Dataverse"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Connectors","sub":null,"explanation":"Connectors link apps, data, and devices in the cloud — bridges for information and commands. There are more than 1,400 prebuilt connectors (Salesforce, Office 365, Dropbox, Google, etc.) used by Power Apps, Power Automate flows, and logic apps.","source":{"title":"Describe the value of connectors (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/4-describe-value-connectors-integrate-services-data"}},{"id":"ml-5","sourceBank":"microsoft-learn","type":"single","question":"What is the business value of Microsoft Dataverse in Power Platform?","options":["It is a charting tool","It is a scalable, secure data service and app platform that is the foundation enabling Power Platform components to work together with a common data model","It only stores files","It is a desktop automation tool"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Dataverse","sub":null,"explanation":"Dataverse is a scalable data service and app platform that lets users securely store and manage data from multiple sources using a common data model — the foundation that enables Power Platform components to work together.","source":{"title":"Describe the value of Microsoft Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/5-describe-value-microsoft-dataverse-organize-business-data"}},{"id":"ml-6","sourceBank":"microsoft-learn","type":"single","question":"What is Microsoft Copilot Studio in the Power Platform?","options":["A relational database","A low-code tool for building copilots/agents and configuring generative AI, including customizing Microsoft 365 Copilot and building standalone agents","A data visualization service","A connector for SharePoint"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Copilots & Copilot Studio","sub":null,"explanation":"Microsoft Copilot Studio is a low-code tool that combines conversational capabilities (custom GPTs, generative AI plugins, and manual topics) to customize Microsoft 365 Copilot and build standalone agents — part of Power Platform's generative AI value.","source":{"title":"Describe the value of Copilots and generative AI (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/8-describe-value-copilots-generative-ai-features-microsoft-power-platform"}},{"id":"ml-7","sourceBank":"microsoft-learn","type":"single","question":"What is Power Fx?","options":["A cloud database","The low-code programming language used across Power Platform, using Excel-like formulas","A type of connector","A Power Automate trigger"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Value of Power Fx","sub":null,"explanation":"Power Fx is the low-code programming language used across Power Platform. It is easy to learn and uses Excel-like formulas to create application logic.","source":{"title":"Describe the value of Power Fx (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/6-describe-value-power-fx-low-code-solution"}},{"id":"ml-8","sourceBank":"microsoft-learn","type":"single","question":"How does Power Platform extend Microsoft 365, including Teams?","options":["It replaces Microsoft 365 entirely","It integrates with Microsoft 365 apps and Teams — e.g., embedding apps and automating processes across Teams, Outlook, and SharePoint — to deliver solutions where users already work","It only works as a standalone product with no Microsoft 365 integration","It can only connect to non-Microsoft services"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Power Platform with Microsoft 365 / Teams","sub":null,"explanation":"Power Platform business solutions work together with Microsoft 365 apps and services, including Microsoft Teams — for example, building and embedding apps in Teams and automating cross-app processes (Outlook, SharePoint) — so solutions reach users where they already work.","source":{"title":"Describe how Power Platform services work together (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/7-describe-how-power-platform-services-work-together"}},{"id":"ml-9","sourceBank":"microsoft-learn","type":"single","question":"In an employee-onboarding solution, how might Power Platform services work together?","options":["Only Power BI is used end to end","Power Apps provides the app, Power Automate handles notifications/approvals, and Dataverse securely stores the employee data","Each service runs in isolation with no shared data","Power Pages stores all the relational data"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Services Working Together","sub":null,"explanation":"Power Platform is an interconnected ecosystem. For onboarding, a Power Apps app lets new hires upload documents and track progress, Power Automate handles notifications and approvals, and Dataverse securely stores the data — with Power BI for insights.","source":{"title":"Describe how Power Platform services work together (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/7-describe-how-power-platform-services-work-together"}},{"id":"ml-10","sourceBank":"microsoft-learn","type":"single","question":"Which is an advantage of Microsoft Dataverse over a traditional database?","options":["It requires more manual coding to secure","It provides built-in features out of the box — rich metadata, defined relationships, integrated business logic, and role-based security","It cannot store relational data","It only supports a single table"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Dataverse vs Traditional Databases","sub":null,"explanation":"While both use tables, Dataverse enhances them with built-in rich metadata, defined relationships, integrated business logic, and out-of-the-box security (role-based, row-level, column-level encryption) — and supports low-code/no-code development, unlike traditional databases that need manual setup and coding.","source":{"title":"Differences between traditional databases and Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/2-describe-differences-between-traditional-databases-microsoft-dataverse"}},{"id":"ml-11","sourceBank":"microsoft-learn","type":"single","question":"In Dataverse, a single customer can have many orders. Which relationship type models this?","options":["Many-to-many (N:N)","One-to-many (1:N)","One-to-one (1:1)","No relationship is needed"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Dataverse Relationships","sub":null,"explanation":"A one-to-many (1:N) relationship lets a single row in the primary table relate to multiple rows in the related table (e.g., a customer with many orders), commonly used for parent-child associations. Many-to-many (N:N) uses an intersect table.","source":{"title":"Tables, columns, and relationships in Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/3-describe-tables-columns-relationships-microsoft-dataverse"}},{"id":"ml-12","sourceBank":"microsoft-learn","type":"single","question":"Which Dataverse feature lets you validate data or automate actions directly at the data layer without writing code?","options":["Business rules","Power Pages themes","Connectors","Desktop flows"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Dataverse Business Logic","sub":null,"explanation":"Dataverse offers options for business logic — such as business rules — that enforce validation and automate actions at the data layer (applied across any app using the table), along with related components like keys, forms, views, and dashboards.","source":{"title":"Options for business logic in Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/4-describe-options-business-logic-microsoft-dataverse"}},{"id":"ml-13","sourceBank":"microsoft-learn","type":"single","question":"Which statement about getting data into Dataverse is correct?","options":["Data can only be entered manually one row at a time","Dataverse supports importing and exporting data (for example, from Excel/CSV and other sources)","Dataverse cannot exchange data with other systems","Only developers using code can import data"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Importing & Exporting Data","sub":null,"explanation":"Dataverse provides options for importing and exporting data — for example bringing data in from Excel/CSV and other sources and exporting it — so makers can populate and integrate tables without writing code.","source":{"title":"Options for importing and exporting data (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/6-describe-options-importing-exporting-data"}},{"id":"ml-14","sourceBank":"microsoft-learn","type":"single","question":"How does Power Platform control what actions a user can perform and what data they can access?","options":["Through role-based access control (RBAC) using security roles at environment, app, and record levels","By giving every user full administrator rights","Only through Power Pages themes","By disabling Microsoft Entra ID"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Security Model — RBAC","sub":null,"explanation":"The Power Platform security model uses role-based access control (RBAC): administrators assign security roles that define allowed actions and data access at the environment, app, and record levels, following least-privilege access.","source":{"title":"Describe the Power Platform security model (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/2-describe-microsoft-power-platform-security-model"}},{"id":"ml-15","sourceBank":"microsoft-learn","type":"single","question":"What do Data Loss Prevention (DLP) policies do in Power Platform?","options":["Encrypt Power Pages themes","Categorize connectors as business vs non-business and block data from flowing between the two groups","Create model-driven apps","Schedule cloud flows"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Data Loss Prevention (DLP)","sub":null,"explanation":"DLP policies categorize connectors into business and non-business groups and block data transfers between the groups, keeping sensitive data within trusted connectors. They can be applied at environment or tenant level.","source":{"title":"Describe the Power Platform security model (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/2-describe-microsoft-power-platform-security-model"}},{"id":"ml-16","sourceBank":"microsoft-learn","type":"single","question":"What is a Power Platform environment?","options":["A type of connector","A container that holds an organization's apps, flows, and data, tied to a Microsoft Entra tenant and a geographic location","A Power Fx formula","A Power BI dashboard"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Environments","sub":null,"explanation":"Environments are containers that hold business data, apps, and flows. Each is created under a Microsoft Entra tenant and tied to a geographic location, letting you separate resources by team, purpose (dev/test/prod), or region for security and compliance.","source":{"title":"Describe Power Platform environments (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/3-describe-environments"}},{"id":"ml-17","sourceBank":"microsoft-learn","type":"single","question":"Where do administrators manage Power Platform environments, DLP policies, and tenant settings?","options":["The Power Platform admin center","Power Apps Studio only","The Power Pages design studio","Microsoft Word"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Admin Centers & Portals","sub":null,"explanation":"The Power Platform admin center is the primary portal where administrators manage environments, data policies (DLP), analytics, and other governance settings across the tenant.","source":{"title":"Power Platform admin centers and portals (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/4-describe-different-microsoft-power-platform-admin-centers-portals"}},{"id":"ml-18","sourceBank":"microsoft-learn","type":"single","question":"How does Power Platform support compliance and inclusive design?","options":["It ignores regional regulations","It supports data privacy (e.g., region-bound environments, governance) and accessibility guidelines so solutions are compliant and usable by everyone","It only works in one country","Accessibility is not a consideration in Power Platform"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Data Privacy & Accessibility","sub":null,"explanation":"Power Platform supports data privacy and accessibility guidelines — for example geographically bound environments to meet data-residency/compliance needs, governance via the Trust Center/compliance offerings, and accessibility guidance so apps are usable by everyone.","source":{"title":"Data privacy and accessibility guidelines (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/5-describe-power-platform-data-privacy-accessibility-guidelines"}},{"id":"ml-19","sourceBank":"microsoft-learn","type":"single","question":"Which scenario is best suited to a canvas app?","options":["A field app with a custom, pixel-perfect UI that connects to multiple data sources and uses the device camera","A back-office records-management app driven entirely by a Dataverse data model","A relational database engine","An external public website"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Canvas App Use Cases","sub":null,"explanation":"Canvas apps give you a custom, pixel-perfect UI, can connect to many data sources (Dataverse or not), are easily embeddable, and integrate with device features (like the camera) — ideal for task/screen-focused apps such as a field worker app.","source":{"title":"Describe use cases of canvas apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/3-describe-use-cases-canvas-apps"}},{"id":"ml-20","sourceBank":"microsoft-learn","type":"single","question":"Which statement about model-driven apps is true?","options":["They can be built on any data source without Dataverse","They are built on top of Microsoft Dataverse and generate a responsive, consistent UI from the underlying data model","They require pixel-by-pixel UI design for every screen","They cannot use security roles"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Model-driven App Use Cases","sub":null,"explanation":"Model-driven apps can only be built on top of Dataverse. The UI is largely generated from the data model and is responsive/consistent, with data-relationship navigation and security trimming — ideal for back-office, process-focused solutions.","source":{"title":"Describe use cases of model-driven apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/4-describe-use-cases-model-driven-apps"}},{"id":"ml-21","sourceBank":"microsoft-learn","type":"single","question":"Which components are central to a model-driven app's structure?","options":["Forms, views, and the Dataverse tables/relationships they surface","Power Pages themes","Desktop flow recordings","Connectors only, with no data model"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Model-driven App Features","sub":null,"explanation":"Model-driven apps surface Dataverse data through components like forms, views, charts, and dashboards, and use the data model's relationships for navigation — letting makers compose apps from tables without custom-coding the UI.","source":{"title":"Explore model-driven app features (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/5-explore-model-driven-app-features"}},{"id":"ml-22","sourceBank":"microsoft-learn","type":"single","question":"Your app will NOT use a Dataverse database. Which Power Apps type must you use?","options":["Model-driven app","Canvas app","Either works equally","Neither — you need Power Pages"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Choosing Canvas vs Model-driven","sub":null,"explanation":"If the app isn't connected to a Dataverse database, you must build a canvas app, because model-driven apps can only be built on top of Dataverse. Many real solutions combine both types.","source":{"title":"Differences between canvas and model-driven apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/6-describe-differences-between-canvas-apps-model-driven-apps"}},{"id":"ml-23","sourceBank":"microsoft-learn","type":"single","question":"How does a canvas app get data from systems like SharePoint, SQL, or Dataverse?","options":["By using connectors to connect to those data sources","Only by manual data entry","Through Power Pages themes","It cannot connect to external data"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Connecting Canvas Apps to Data","sub":null,"explanation":"Canvas apps connect to data sources by using connectors — Dataverse, SharePoint, SQL, Excel, and 1,400+ others — letting makers read and write business data from within the app.","source":{"title":"Build a canvas app: Connect to data sources (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/2-connect-data-sources-use-connectors"}},{"id":"ml-24","sourceBank":"microsoft-learn","type":"single","question":"In a canvas app, what are controls such as text input boxes, buttons, galleries, and forms used for?","options":["Building the app's user interface and interactions on a screen","Defining Dataverse relationships","Creating DLP policies","Scheduling cloud flows"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Canvas Controls","sub":null,"explanation":"Controls (labels, text inputs, buttons, galleries, forms, etc.) are the building blocks of a canvas app screen — makers add and configure them to build the UI and user interactions.","source":{"title":"Build a canvas app: Describe common controls (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/4-describe-common-controls"}},{"id":"ml-25","sourceBank":"microsoft-learn","type":"single","question":"Which canvas app feature helps build layouts that adapt to different screen sizes?","options":["Containers","Desktop flows","Process Mining","Sensitivity labels"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Responsive Containers","sub":null,"explanation":"Containers let makers build responsive pages in a canvas app, grouping and arranging controls so the layout adapts across device and screen sizes.","source":{"title":"Build a canvas app: Build responsive pages using containers (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/5-build-responsive-pages-use-containers"}},{"id":"ml-26","sourceBank":"microsoft-learn","type":"single","question":"What do Copilot controls add to a canvas app?","options":["AI-assisted, conversational experiences for end users within the app","A new Dataverse table","A DLP policy","A desktop flow"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Copilot Controls","sub":null,"explanation":"Copilot controls let makers add AI-assisted, conversational capabilities into a canvas app so end users can interact with their app data using natural language.","source":{"title":"Build a canvas app: Copilot controls (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/8-describe-capabilities-copilot-controls"}},{"id":"ml-27","sourceBank":"microsoft-learn","type":"single","question":"After building a canvas app, how do you make it available to colleagues?","options":["Share the app with users or groups (assigning appropriate access)","Email the source code","Publish it as a public website automatically","Apps cannot be shared"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Sharing a Canvas App","sub":null,"explanation":"You share a canvas app with specific users or security groups, granting them access to run (and optionally co-edit) it. Managed Environments can restrict how broadly apps may be shared.","source":{"title":"Build a canvas app: Share a canvas app (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/11-share-canvas-app"}},{"id":"ml-28","sourceBank":"microsoft-learn","type":"single","question":"What is the starting point for building a model-driven app?","options":["Designing each screen pixel by pixel","The Dataverse tables (and their relationships) that the app will surface","A Power Pages template","A desktop flow recording"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3C","topic":"Building Model-driven Apps","sub":null,"explanation":"Model-driven apps are built data-first: you create the app from Dataverse tables, and the app surfaces those tables through forms and views — the UI is driven by the data model rather than designed screen by screen.","source":{"title":"Build a model-driven app (Training)","url":"https://learn.microsoft.com/training/modules/build-model-driven-app/"}},{"id":"ml-29","sourceBank":"microsoft-learn","type":"single","question":"In a model-driven app, what does a form define?","options":["How an individual record's fields are laid out for viewing and editing","A scheduled cloud flow","A connector group for DLP","The site theme"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3C","topic":"Modifying Forms","sub":null,"explanation":"Forms in a model-driven app define how a single record's columns are arranged for viewing and data entry. Makers can modify forms to control which fields appear and how they're organized.","source":{"title":"Build a model-driven app (Training)","url":"https://learn.microsoft.com/training/modules/build-model-driven-app/"}},{"id":"ml-30","sourceBank":"microsoft-learn","type":"single","question":"In a model-driven app, what does a view provide?","options":["A configurable list of records (with columns, filters, and sort) for a table","A single record's edit screen","A Power Automate trigger","A Power Pages theme"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3C","topic":"Views & Sharing","sub":null,"explanation":"A view defines a list of records for a table — which columns appear, plus filtering and sorting. Makers create and modify views, and then share the model-driven app with users via security roles.","source":{"title":"Build a model-driven app (Training)","url":"https://learn.microsoft.com/training/modules/build-model-driven-app/"}},{"id":"ml-31","sourceBank":"microsoft-learn","type":"single","question":"Why is a model-driven app described as 'data-first'?","options":["Because its UI and structure are generated from the Dataverse data model rather than custom-designed per screen","Because it can't display any data","Because it only works offline","Because it requires Power Fx for every control"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Model-driven UI Generation","sub":null,"explanation":"Model-driven apps are data-first: the layout and components are largely generated from the underlying Dataverse tables, relationships, forms, and views — giving a consistent, responsive UI with less manual design than canvas apps.","source":{"title":"Differences between canvas and model-driven apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/6-describe-differences-between-canvas-apps-model-driven-apps"}},{"id":"ml-32","sourceBank":"microsoft-learn","type":"single","question":"Which capability is characteristic of canvas apps?","options":["They can be easily embedded (e.g., in Teams or a model-driven form) and use device features like the camera and GPS","They can never be embedded anywhere","They can only run on desktop browsers","They cannot connect to Dataverse"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Embedding & Device Integration","sub":null,"explanation":"Canvas apps offer a custom UI, easy embeddability (e.g., embedded in a model-driven form or Teams), and device integration such as camera and location — strengths for task-focused mobile/field scenarios.","source":{"title":"Differences between canvas and model-driven apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/6-describe-differences-between-canvas-apps-model-driven-apps"}},{"id":"ml-33","sourceBank":"microsoft-learn","type":"single","question":"Which type of Power Automate flow is best for automating a legacy desktop application that has no API, by simulating clicks and keystrokes?","options":["Cloud flow","Desktop flow","Scheduled cloud flow","Instant cloud flow"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Cloud vs Desktop Flows","sub":null,"explanation":"Desktop flows (robotic process automation) automate tasks on the local machine — including legacy apps without APIs — by simulating UI actions like clicking buttons and entering text. Cloud flows automate across online services.","source":{"title":"Describe use cases for cloud and desktop flows (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/3-describe-use-cases-cloud-desktop-flows"}},{"id":"ml-34","sourceBank":"microsoft-learn","type":"single","question":"What is the benefit of using a cloud flow template in Power Automate?","options":["It provides a prebuilt starting point you can customize, instead of building a flow from scratch","It is a relational database","It permanently locks the flow from editing","It only works for desktop flows"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Cloud Flow Templates","sub":null,"explanation":"Power Automate offers prebuilt cloud flow templates for common scenarios that you can use as a starting point and customize — accelerating flow creation versus building from a blank flow.","source":{"title":"Describe use cases for cloud flow templates (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/4-describe-use-cases-cloud-flow-templates"}},{"id":"ml-35","sourceBank":"microsoft-learn","type":"single","question":"In a Power Automate cloud flow, what starts the flow and what does the work after it starts?","options":["A trigger starts the flow; actions perform the tasks that follow","An action starts the flow; triggers perform the tasks","A connector starts the flow; a theme performs the tasks","A view starts the flow; a form performs the tasks"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Triggers, Actions & Connectors","sub":null,"explanation":"A trigger is the event that initiates a cloud flow (e.g., 'when a new email arrives'); actions are the tasks the flow then performs (e.g., save attachment, post a Teams message). Connectors are the bridges to the services these triggers and actions use.","source":{"title":"How cloud flows use connector triggers and actions (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/5-describe-how-power-automate-cloud-flows-use-connector-triggers-actions"}},{"id":"ml-36","sourceBank":"microsoft-learn","type":"single","question":"A flow needs to run automatically every Monday at 8 AM. Which trigger type is appropriate?","options":["Instant (manual) trigger","Automated trigger","Scheduled trigger","Desktop trigger"],"correct":[2],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Trigger Types","sub":null,"explanation":"A scheduled trigger runs a flow at specific times or recurring intervals (e.g., every Monday at 8 AM). Instant triggers run on demand (button press); automated triggers fire when an external event occurs.","source":{"title":"How cloud flows use connector triggers and actions (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/5-describe-how-power-automate-cloud-flows-use-connector-triggers-actions"}},{"id":"ml-37","sourceBank":"microsoft-learn","type":"single","question":"Which control capability lets a cloud flow take different paths based on a condition, or repeat actions over a set of items?","options":["Branching (conditions) and loops","Sensitivity labels","Power Pages themes","Dataverse views"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Loops & Branching","sub":null,"explanation":"Cloud flows support control logic — branching with conditions (take different paths based on a test) and loops (repeat actions over each item in a collection) — to handle more complex automation.","source":{"title":"Describe loops and branching in cloud flows (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/6-describe-loops-branching-cloud-flows"}},{"id":"ml-38","sourceBank":"microsoft-learn","type":"single","question":"Which is a common Power Automate use case?","options":["Routing a document or request through an approval process and notifying approvers in Teams or Outlook","Designing a Power Pages theme","Creating a Dataverse relationship","Building a Power BI semantic model"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Approvals & Common Use Cases","sub":null,"explanation":"Power Automate is commonly used for approvals — routing requests to approvers with notifications in Teams or Outlook — as well as scenarios across SharePoint, Forms, and document automation.","source":{"title":"Power Automate use cases for approvals (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/7-describe-power-automate-use-cases-approvals"}},{"id":"ml-39","sourceBank":"microsoft-learn","type":"single","question":"Which app is used to build and run desktop (RPA) automations on a Windows machine?","options":["Power Automate for desktop","Power BI Desktop","Power Apps Studio","Power Pages design studio"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Power Automate Apps","sub":null,"explanation":"Power Automate for desktop is the application for building and running desktop flows (RPA). The Power Automate family also includes the Power Automate mobile app and the web-based maker portal.","source":{"title":"Describe the Power Automate apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/8-describe-power-automate-apps"}},{"id":"ml-40","sourceBank":"microsoft-learn","type":"single","question":"What is the purpose of Process Mining in Power Automate?","options":["To analyze how business processes actually run and identify bottlenecks and automation opportunities","To store relational data","To design website themes","To assign security roles"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Process Mining","sub":null,"explanation":"Process Mining analyzes an organization's real process data to reveal how processes actually flow, surfacing bottlenecks and opportunities to automate or optimize — helping decide where to apply Power Automate.","source":{"title":"Describe process mining (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/2-describe-process-mining"}},{"id":"ml-41","sourceBank":"microsoft-learn","type":"single","question":"After building a cloud flow, which step lets you confirm it works correctly before relying on it?","options":["Run/test the flow and review its run history","Delete the trigger","Convert it to a Power Pages site","Assign it a sensitivity label"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Building & Testing a Flow","sub":null,"explanation":"When you build a cloud flow you choose an instant, automated, or scheduled trigger, then run and test it and review the run history to confirm it behaves correctly. You can also create/modify flows through conversation (Copilot) and share them.","source":{"title":"Build a Microsoft Power Automate flow (Training)","url":"https://learn.microsoft.com/training/modules/build-microsoft-power-automate-flow/"}},{"id":"ml-42","sourceBank":"microsoft-learn","type":"single","question":"Which scenario is a good fit for Power Pages?","options":["An external customer self-service portal where customers submit support tickets and track orders against Dataverse data","An internal back-office records app for staff","A desktop RPA automation","A Power BI dashboard"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Power Pages Use Cases","sub":null,"explanation":"Power Pages is ideal for secure external-facing websites — like customer self-service portals where external users view and interact with Dataverse business data (submit tickets, track orders). For internal apps, Power Apps is the better fit.","source":{"title":"Describe use cases for Power Pages (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/2-describe-use-cases-power-pages"}},{"id":"ml-43","sourceBank":"microsoft-learn","type":"single","question":"Which are valid ways to start creating a Power Pages site?","options":["Start from a template, from a blank site, or use Copilot to generate a site by describing it","Only by writing HTML from scratch","Only by importing an Excel file","Only through a desktop flow"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Methods for Creating Sites","sub":null,"explanation":"Power Pages sites can be created from prebuilt templates, from a blank starting point, or by using Copilot to generate a site from a natural-language description — then customized in the design studio.","source":{"title":"Describe methods for creating sites (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/3-describe-methods-create-sites"}},{"id":"ml-44","sourceBank":"microsoft-learn","type":"single","question":"How does Power Pages control what anonymous and authenticated visitors can see or do?","options":["Through security features such as authentication and table/web-page permissions and roles","By making all data public to everyone","Through DLP connector groups only","It has no security model"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Power Pages Security","sub":null,"explanation":"Power Pages includes a security model — authentication for external users plus permissions/roles that control access to pages and to the underlying Dataverse tables — so you expose only the right data to the right audience.","source":{"title":"Describe Power Pages security concepts (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/4-describe-power-pages-security-concepts"}},{"id":"ml-45","sourceBank":"microsoft-learn","type":"single","question":"How can Copilot speed up building a Power Pages site?","options":["By generating pages, text, and even Dataverse tables/forms from a natural-language description of the site","By writing the site's server firmware","By replacing the design studio entirely with code","Copilot cannot be used with Power Pages"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Creating Sites with Copilot","sub":null,"explanation":"Power Pages Copilot lets makers describe the site they want in natural language; Copilot helps generate pages, content, and supporting Dataverse structures — streamlining site creation before refining in the design studio.","source":{"title":"Create a Microsoft Power Pages site (Training)","url":"https://learn.microsoft.com/training/modules/create-microsoft-power-pages-site/"}},{"id":"ml-46","sourceBank":"microsoft-learn","type":"single","question":"Where do Power Pages makers spend most of their time building and customizing a site?","options":["The Power Pages design studio (with workspaces such as Pages, Styling, Data, and Set up)","The Power BI service","Power Automate for desktop","The Exchange admin center"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Design Studio Workspaces","sub":null,"explanation":"Makers build sites in the Power Pages design studio, which organizes work into workspaces — for example Pages, Styling, Data, and Set up — to add pages, style the site, connect Dataverse data, and configure security/behavior.","source":{"title":"Create a Microsoft Power Pages site (Training)","url":"https://learn.microsoft.com/training/modules/create-microsoft-power-pages-site/"}},{"id":"ml-47","sourceBank":"microsoft-learn","type":"single","question":"In the Power Pages design studio, what can a maker do to customize a site's look and content?","options":["Add and configure pages and components, and modify the site's theme (colors, fonts, styling)","Only change the database schema","Only schedule cloud flows","Nothing — sites cannot be customized"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Pages, Components & Themes","sub":null,"explanation":"Makers create and modify pages, add and configure components (text, forms, lists, etc.), and modify the site theme (colors, fonts, and styling) to tailor the look and content of the Power Pages site.","source":{"title":"Create a Microsoft Power Pages site (Training)","url":"https://learn.microsoft.com/training/modules/create-microsoft-power-pages-site/"}},{"id":"ml-48","sourceBank":"microsoft-learn","type":"single","question":"What data does a Power Pages site typically surface to its external audience?","options":["Shared business data stored in Microsoft Dataverse","Only static text with no data","Data that can never be secured","Only data from desktop flows"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Power Pages & Dataverse","sub":null,"explanation":"Power Pages builds sites on the same shared business data stored in Microsoft Dataverse used by other Power Platform components, letting external audiences securely view and interact with that data.","source":{"title":"Describe use cases for Power Pages (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/2-describe-use-cases-power-pages"}},{"id":"ml-101","sourceBank":"microsoft-learn","type":"single","question":"What does the Common Data Model (CDM) provide to Microsoft Dataverse?","options":["Standardized, predefined schemas (tables, attributes, relationships) for common business concepts so systems interoperate consistently","A way to build desktop flows","A Power Pages theme","A connector for Twitter/X"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Common Data Model","sub":null,"explanation":"The Common Data Model is a standardized schema at the core of Dataverse. It provides predefined schemas for common business concepts (accounts, contacts, etc.), so data is organized consistently and different systems and apps interoperate easily.","source":{"title":"Differences between traditional databases and Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/2-describe-differences-between-traditional-databases-microsoft-dataverse"}},{"id":"ml-102","sourceBank":"microsoft-learn","type":"single","question":"Approximately how many prebuilt connectors does Power Platform offer to integrate with other services?","options":["About 10","More than 1,400","Exactly 50","None — you must build them all"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Connectors at Scale","sub":null,"explanation":"Power Platform provides more than 1,400 prebuilt connectors (Salesforce, Office 365, Dropbox, Google services, and more), used by Power Apps, Power Automate, and logic apps to integrate data and actions seamlessly.","source":{"title":"Explore Microsoft Power Platform (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/2-explore-microsoft-power-platform"}},{"id":"ml-103","sourceBank":"microsoft-learn","type":"single","question":"Why is Power Fx considered approachable for low-code makers?","options":["It uses Excel-like formulas that are easy to learn","It requires C# expertise","It is only usable by administrators","It can only run on desktop flows"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Power Fx Familiarity","sub":null,"explanation":"Power Fx is the low-code language across Power Platform and uses Excel-like formulas, making it easy for makers familiar with spreadsheets to learn and use when building app logic.","source":{"title":"Describe the value of Power Fx (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/6-describe-value-power-fx-low-code-solution"}},{"id":"ml-104","sourceBank":"microsoft-learn","type":"single","question":"What does it mean that Power Platform 'democratizes' technology?","options":["It lowers the barrier to entry so users across departments can build apps and workflows with low-code, not just professional developers","It removes all security controls","It only allows IT administrators to build apps","It requires every user to learn to code"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Democratizing Development","sub":null,"explanation":"A transformative aspect of Power Platform is democratizing technology: its low-code environment lowers the barrier to entry, empowering business users across departments to build applications and workflows while maintaining enterprise governance.","source":{"title":"Describe how Power Platform services work together (Training)","url":"https://learn.microsoft.com/training/modules/describe-business-value-microsoft-power-platform-services/7-describe-how-power-platform-services-work-together"}},{"id":"ml-105","sourceBank":"microsoft-learn","type":"single","question":"Students can enroll in many courses, and each course can have many students. Which Dataverse relationship models this, and how is it implemented?","options":["Many-to-many (N:N), implemented through an intersect table","One-to-many (1:N), implemented with a single lookup","One-to-one (1:1), implemented with a primary key","No relationship is possible"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Many-to-many Relationships","sub":null,"explanation":"A many-to-many (N:N) relationship lets rows in each table relate to multiple rows in the other. It's managed through an intersect table that maps the relationships between the two tables.","source":{"title":"Tables, columns, and relationships in Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/3-describe-tables-columns-relationships-microsoft-dataverse"}},{"id":"ml-106","sourceBank":"microsoft-learn","type":"single","question":"Which statements about Dataverse tables are correct?","options":["Relationships are created using lookup columns, and each row's primary key is a GUID","Tables can't relate to each other","The primary key must be a person's name","Lookup columns store images only"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Lookup Columns & Keys","sub":null,"explanation":"In Dataverse, lookup columns reference rows in another table to create relationships, and each row's primary key is a Globally Unique Identifier (GUID) that uniquely identifies it.","source":{"title":"Tables, columns, and relationships in Dataverse (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-dataverse/3-describe-tables-columns-relationships-microsoft-dataverse"}},{"id":"ml-107","sourceBank":"microsoft-learn","type":"single","question":"Which Power Platform environment is automatically created for a tenant and shared by all licensed users?","options":["Sandbox environment","Default environment","Trial environment","Developer environment"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Environment Types","sub":null,"explanation":"The Default environment is automatically created for each tenant and is shared by all users (all licensed users get the Environment Maker role). Production and Sandbox environments give full control; Trial environments expire after 30 days.","source":{"title":"Describe Power Platform environments (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/3-describe-environments"}},{"id":"ml-108","sourceBank":"microsoft-learn","type":"single","question":"What do Managed Environments add to standard Power Platform environments?","options":["Enhanced governance — e.g., limiting how broadly apps are shared, weekly usage insights, data policies, and solution checker","The ability to store more rows only","A new programming language","Nothing different from a default environment"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Managed Environments","sub":null,"explanation":"Managed Environments add enhanced administrative and governance capabilities — limiting app sharing, weekly usage insights, data policies, pipelines, and solution checker — so admins keep control and compliance as adoption scales.","source":{"title":"Describe Power Platform environments (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/3-describe-environments"}},{"id":"ml-109","sourceBank":"microsoft-learn","type":"single","question":"Which statements describe Power Platform's built-in data protection?","options":["Microsoft Entra ID handles identity (with MFA and Conditional Access), and data is encrypted at rest (AES-256) and in transit (TLS)","Data is never encrypted","Authentication is optional and off by default","Encryption only applies to Power Pages"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Encryption & Identity","sub":null,"explanation":"Power Platform's security model uses Microsoft Entra ID for identity (supporting MFA and Conditional Access) and encrypts data at rest with AES 256-bit and in transit with TLS — helping meet compliance standards like GDPR and HIPAA.","source":{"title":"Describe the Power Platform security model (Training)","url":"https://learn.microsoft.com/training/modules/describe-microsoft-power-platform-administration-governance/2-describe-microsoft-power-platform-security-model"}},{"id":"ml-110","sourceBank":"microsoft-learn","type":"single","question":"Which need points toward a model-driven app rather than a canvas app?","options":["A back-office, process-focused solution over Dataverse needing consistent UI, data-relationship navigation, and security trimming","A highly custom, pixel-perfect UI connected to non-Dataverse data","A site for external anonymous customers","A desktop RPA automation"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"When to Use Model-driven","sub":null,"explanation":"Model-driven apps suit back-office, process-focused work on Dataverse, where a responsive consistent UI, data-relationship navigation, and security-trimmed UI matter more than pixel-perfect custom design.","source":{"title":"Differences between canvas and model-driven apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-basic-microsoft-power-apps-capabilities/6-describe-differences-between-canvas-apps-model-driven-apps"}},{"id":"ml-111","sourceBank":"microsoft-learn","type":"single","question":"Which statement about canvas app data sources is correct?","options":["A canvas app can connect to Dataverse and to many non-Dataverse sources (SharePoint, SQL, Excel, third-party services) via connectors","A canvas app can only use Dataverse","A canvas app cannot connect to any data","A canvas app can only use one data source ever"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Canvas App Data Flexibility","sub":null,"explanation":"Canvas apps are flexible on data: they connect via connectors to Dataverse and many other sources (SharePoint, SQL, Excel, Google services, and more), and can even combine multiple sources in one app.","source":{"title":"Build a canvas app: Connect to data sources (Training)","url":"https://learn.microsoft.com/training/modules/build-canvas-app/2-connect-data-sources-use-connectors"}},{"id":"ml-112","sourceBank":"microsoft-learn","type":"single","question":"In a model-driven app, what is the difference between a form and a view?","options":["A form shows one record's fields for viewing/editing; a view shows a filterable, sortable list of many records","They are the same thing","A form lists many records; a view shows one record","Neither relates to Dataverse data"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3C","topic":"Forms vs Views","sub":null,"explanation":"A form lays out a single record's columns for viewing and editing, while a view presents a list of records (with selected columns, filtering, and sorting). Makers configure both, then share the app via security roles.","source":{"title":"Build a model-driven app (Training)","url":"https://learn.microsoft.com/training/modules/build-model-driven-app/"}},{"id":"ml-113","sourceBank":"microsoft-learn","type":"single","question":"Which set correctly lists the three types of Power Automate cloud flows?","options":["Automated, instant, and scheduled","Canvas, model-driven, and portal","Bronze, silver, and gold","Block, page, and append"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Cloud Flow Types","sub":null,"explanation":"Cloud flows come in three types: automated (triggered by an event), instant (triggered manually, e.g., a button), and scheduled (run at set times/intervals).","source":{"title":"Describe use cases for cloud and desktop flows (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/3-describe-use-cases-cloud-desktop-flows"}},{"id":"ml-114","sourceBank":"microsoft-learn","type":"single","question":"Where can a maker browse templates and build cloud flows in a web browser?","options":["The Power Automate maker portal (make.powerautomate.com)","Power Automate for desktop only","The Power Pages design studio","The Power BI service"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Maker Portal","sub":null,"explanation":"The Power Automate maker portal is the web-based home for creating and managing cloud flows and browsing templates. The Power Automate family also includes Power Automate for desktop (RPA) and the mobile app.","source":{"title":"Describe the Power Automate apps (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/8-describe-power-automate-apps"}},{"id":"ml-115","sourceBank":"microsoft-learn","type":"single","question":"A flow triggers when an Outlook email arrives, saves the attachment to OneDrive, and notifies a channel in Teams. What makes this cross-app flow possible?","options":["Connectors for Outlook, OneDrive, and Teams provide the trigger and actions","A single Dataverse table","A Power Pages theme","A desktop flow recording"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Combining Connectors","sub":null,"explanation":"Connectors are the bridges to each service: the Outlook connector provides the trigger, and the OneDrive and Teams connectors provide actions. Combining connectors lets one flow automate work across multiple apps.","source":{"title":"How cloud flows use connector triggers and actions (Training)","url":"https://learn.microsoft.com/training/modules/identify-microsoft-power-automate-components/5-describe-how-power-automate-cloud-flows-use-connector-triggers-actions"}},{"id":"ml-116","sourceBank":"microsoft-learn","type":"single","question":"How can a Power Pages site differentiate what anonymous visitors versus signed-in users can access?","options":["By configuring authentication and permissions/roles that control access to pages and Dataverse tables","By making everything public","By using DLP connector groups","Power Pages has no way to differentiate access"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Authenticated vs Anonymous Access","sub":null,"explanation":"Power Pages security lets you require authentication and assign permissions/roles that govern which pages and Dataverse table data each audience (anonymous or authenticated) can access — exposing only the appropriate content.","source":{"title":"Describe Power Pages security concepts (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/4-describe-power-pages-security-concepts"}},{"id":"ml-117","sourceBank":"microsoft-learn","type":"single","question":"What is the benefit of starting a Power Pages site from a template?","options":["Templates are pre-configured solutions that accelerate deployment for specific scenarios and audiences","Templates lock the site so it can't be edited","Templates remove all security","Templates only work for internal apps"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Templates Accelerate Sites","sub":null,"explanation":"Power Pages templates are pre-configured solutions that accelerate deployment, giving you an environment immediately suited to specific scenarios and audiences that you can then customize in the design studio.","source":{"title":"Describe methods for creating sites (Training)","url":"https://learn.microsoft.com/training/modules/describe-capabilities-microsoft-power-pages/3-describe-methods-create-sites"}},{"id":"gen-1","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A field-service company wants technicians to use a mobile app with a custom, pixel-perfect layout that reflects their branding and connects to existing data sources, built without professional developers. Which Power Platform service best fits this need?","options":["Power Apps","Power Automate","Power Pages","Copilot Studio"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Apps is the low-code/no-code service for building custom business apps, including canvas apps with a tailored, branded UI that connect to many data sources.","source":{"title":"What is Power Apps? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/powerapps-overview"}},{"id":"gen-2","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"The finance department manually forwards every incoming invoice email for manager sign-off, which is slow and error-prone. Which Power Platform service is designed to automate this repetitive approval process?","options":["Power Pages","Power Automate","Dataverse","Power Fx"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate optimizes and automates business processes and workflows, such as routing documents for approval, so repetitive tasks run without manual effort.","source":{"title":"Explore Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/getting-started"}},{"id":"gen-3","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A membership organization wants external customers to register, sign in, and check the status of their support cases through a secure, public-facing website built with low-code tools. Which Power Platform service should they use?","options":["Power Apps","Copilot Studio","Power Pages","Power Automate"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is the low-code service for building secure, external-facing business websites where customers outside the organization can interact with data.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-4","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker building a cloud flow needs it to react to new records in Salesforce and post messages to Slack, but does not want to write custom API integration code. Which Power Platform capability provides the prebuilt triggers and actions to do this?","options":["Dataverse","Power Fx","Power Pages","Connectors"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Connectors provide prebuilt triggers and actions that let makers integrate Power Platform with hundreds of external services and data sources without writing integration code.","source":{"title":"Connectors documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/"}},{"id":"gen-5","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs a secure, cloud-based data store to hold structured business data in tables with relationships, role-based security, and built-in business logic that multiple Power Platform apps can share. Which service meets this need?","options":["Microsoft Dataverse","Power Automate","Connectors","Power Pages"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Microsoft Dataverse securely stores and organizes business data in tables with relationships, security, and logic, serving as a shared foundation for Power Platform solutions.","source":{"title":"What is Microsoft Dataverse? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-intro"}},{"id":"gen-6","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A support team wants to deploy an AI-powered conversational agent that answers common customer questions, built and customized by business users using a low-code, graphical experience. Which Power Platform service is purpose-built for this?","options":["Power Fx","Copilot Studio","Power Apps","Power Pages"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot Studio lets people build and customize AI agents (copilots) with a low-code graphical interface, enabling conversational self-service without traditional coding.","source":{"title":"What is Copilot Studio? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/microsoft-copilot-studio/fundamentals-what-is-copilot-studio"}},{"id":"gen-7","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker customizing a canvas app wants to express logic using a familiar, Excel-like formula syntax rather than a traditional programming language. Which element of Power Platform provides this low-code formula language?","options":["Connectors","Dataverse","Power Fx","Power Automate"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Fx is the low-code, Excel-like formula language used across Power Platform, letting makers write logic with familiar spreadsheet-style expressions.","source":{"title":"Power Fx overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/power-fx/overview"}},{"id":"gen-8","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business analyst with no coding background wants to describe an app she needs in plain English and have Power Platform help generate it. Which aspect of Power Platform's business value does this natural-language, AI-assisted creation represent?","options":["Prebuilt connectors for external systems","Relational data storage in Dataverse","Automated multi-step approvals","Copilots and generative AI"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilots and generative AI let users describe what they need in natural language so Power Platform helps build apps, flows, and more, lowering the barrier for non-developers.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-9","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team lead needs a data-driven internal application whose screens are generated primarily from the underlying table structure and relationships, with consistent forms and views, rather than a hand-designed pixel layout. Which Power Platform service delivers this business value?","options":["Power Apps","Power Pages","Power Automate","Copilot Studio"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Apps includes model-driven apps that generate their UI from the data model, giving component-focused, data-driven applications quickly and with low code.","source":{"title":"What is Power Apps? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/powerapps-overview"}},{"id":"gen-10","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer wants to automate several back-office scenarios: approvals, notifications, and moving files between SharePoint and Outlook. What is the core business value Power Automate delivers here?","options":["Storing relational business data with security roles","Improving productivity by automating recurring processes and workflows","Publishing an external website for customers","Writing Excel-like formulas for app controls"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate's value is improving efficiency by automating recurring business processes and workflows across services, reducing manual, repetitive work.","source":{"title":"Explore Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/getting-started"}},{"id":"gen-11","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company evaluating Power Platform asks what single benefit the connectors library provides across Power Apps, Power Automate, and Copilot Studio. Which statement best describes that value?","options":["It stores business data in relational tables","It generates app screens from a data model","It provides a common set of prebuilt integrations to reach many data sources and services","It hosts secure public websites for external users"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Connectors offer a shared library of prebuilt triggers and actions, so all Power Platform services can integrate with hundreds of external and Microsoft data sources.","source":{"title":"Connectors documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/"}},{"id":"gen-12","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An IT manager is comparing storing app data in scattered spreadsheets versus a managed platform data store. Which benefit is unique to Microsoft Dataverse in this comparison?","options":["It lets users chat with an AI agent","It provides an Excel-like formula language","It publishes a customer-facing website","It provides secure, structured storage with relationships, roles, and business logic managed centrally"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Unlike loose spreadsheets, Dataverse offers centrally managed, secure relational storage with defined tables, relationships, security roles, and built-in logic.","source":{"title":"What is Microsoft Dataverse? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-intro"}},{"id":"gen-13","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A nonprofit wants volunteers outside the organization to browse events and submit applications through a branded portal that enforces sign-in and controlled access to data. Which Power Platform service is intended for this external audience?","options":["Power Pages","Power Apps","Power Automate","Dataverse"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is designed for secure external-facing sites where people outside the organization can view and submit data through a branded, low-code website.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-14","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A product owner wants to understand what Copilot Studio adds to an organization's toolkit. Which description best captures its business value?","options":["A relational database for business data","Low-code building of custom AI agents and copilots for conversational scenarios","A prebuilt library of integration triggers and actions","A formula language for canvas app controls"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot Studio's value is enabling organizations to build and customize AI agents/copilots with low code, delivering conversational experiences and self-service.","source":{"title":"What is Copilot Studio? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/microsoft-copilot-studio/fundamentals-what-is-copilot-studio"}},{"id":"gen-15","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"During a Power Platform overview, a stakeholder asks which characteristic all of the core services share that lowers the cost of building solutions. Which answer is correct?","options":["They all require professional C# developers","They all run only on-premises","They provide low-code/no-code experiences so business users can build solutions faster","They each store data in separate, incompatible formats"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A defining value of Power Platform is its low-code/no-code approach, letting a broad range of users build apps, automations, sites, and agents quickly and affordably.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-16","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to reuse the same familiar expression syntax to set control properties in a canvas app and to shape logic elsewhere in Power Platform. Which statement about Power Fx is accurate?","options":["It is a connector for external SaaS apps","It is a service for hosting public websites","It is a database engine for storing tables","It is a low-code, Excel-inspired formula language used across Power Platform"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Fx is the low-code formula language, modeled on Excel formulas, used across Power Platform to express logic in a familiar, approachable way.","source":{"title":"Power Fx overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/power-fx/overview"}},{"id":"gen-17","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An operations team wants a scheduled process that runs every night, pulls updates from a line-of-business system, and emails a summary, all without a developer writing integration code. Which combination of Power Platform value points does this scenario primarily rely on?","options":["Power Automate for the workflow plus connectors for the integrations","Power Pages for hosting plus Power Fx for formulas","Dataverse for storage plus Copilot Studio for chat","Power Apps for the UI plus Power Pages for the website"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate provides the automated, scheduled workflow, while connectors supply the prebuilt actions to reach the external system and send email without custom code.","source":{"title":"Explore Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/getting-started"}},{"id":"gen-18","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A leadership team asks for a one-line summary of the overall business value of Microsoft Power Platform. Which statement is the best fit?","options":["It is a single spreadsheet program for personal budgeting","It is a suite of low-code services to build apps, automate processes, create sites, analyze and act on data, and add AI-powered experiences","It is exclusively a reporting tool for finance dashboards","It is a hardware platform for on-premises servers"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform is a suite of low-code services (Power Apps, Power Automate, Power Pages, connectors, Dataverse, Copilot Studio, and generative AI) that together let organizations build tailored business solutions.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-19","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker has built a canvas app for tracking equipment and wants colleagues to use it without leaving the collaboration tool where they already chat and meet. Into which Microsoft 365 application can the app be embedded so it appears as a tab for the team?","options":["Microsoft Outlook","Microsoft OneNote","Microsoft Teams","Microsoft Bookings"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Apps integrates with Microsoft Teams so makers can embed canvas and model-driven apps directly in Teams as tabs, letting people use the app inside the collaboration hub they already work in.","source":{"title":"Power Apps and Microsoft Teams integration — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/overview"}},{"id":"gen-20","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A department wants to build a lightweight app inside Microsoft Teams and needs a place to store its data without purchasing a separate standalone Dataverse capacity. Which built-in data store is provided for apps created in Teams?","options":["Dataverse for Teams","A local Excel workbook on each device","SharePoint Server on-premises","An Azure SQL managed instance"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Apps created in Teams with Power Apps use Dataverse for Teams, a built-in, lower-capacity data platform included with Teams, so makers can store relational data without a separate Dataverse license.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-21","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An operations lead wants a flow that posts an adaptive card in a Teams channel and waits for a member to approve or reject a request directly from that card. Which combination makes this possible?","options":["Power Pages hosting the approval form for external users","Copilot Studio answering questions about the request","Dataverse business rules validating the request offline","Power Automate flows integrated with Microsoft Teams"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate integrates with Microsoft Teams, letting flows post adaptive cards and collect responses such as approvals in a channel or chat, so people act on the workflow without leaving Teams.","source":{"title":"Use Power Automate flows in Microsoft Teams — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/teams/overview"}},{"id":"gen-22","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A stakeholder asks why organizations describe Power Platform's value as more than the sum of individual products. Which statement best captures how the services extend one another?","options":["Each service must be licensed and used in complete isolation from the others","The services work together and connect with Microsoft 365 so apps, automation, data, and AI form a single integrated solution","Only Power Apps can connect to data, and the other services cannot share it","The platform replaces Microsoft 365 rather than integrating with it"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A core value of Power Platform is that its services work together and integrate with Microsoft 365, so data, apps, automation, and AI combine into unified business solutions rather than isolated tools.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-23","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team owner in Microsoft Teams wants to add a small app built from a template right inside a channel, using the built-in app-building experience. Where in Teams do they go to create or add these Power Apps?","options":["The Outlook add-ins gallery","The Windows Store desktop catalog","The Power Apps app added within Microsoft Teams","The Azure portal marketplace"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Apps app installed in Microsoft Teams provides the in-Teams building experience, where team members can create apps from templates or from blank and add them to channels.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-24","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company already uses Microsoft 365 and wants makers to reach data in SharePoint, Outlook, and OneDrive from their apps and flows without custom integration work. What makes this straightforward?","options":["Power Platform includes prebuilt connectors to Microsoft 365 services, so apps and flows integrate with them directly","Each Microsoft 365 service must be rebuilt inside Dataverse before it can be used","Only external SaaS systems can be reached; Microsoft 365 data is off-limits","Makers must write custom REST code for every Microsoft 365 service"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform ships prebuilt connectors for Microsoft 365 services like SharePoint, Outlook, and OneDrive, so apps and flows extend and integrate with the tools an organization already uses.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-25","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants users to launch a Teams-embedded canvas app the same way they open other Teams apps, and to pin it to the left rail for quick access. Which capability of the Teams integration supports this?","options":["Publishing the app as a public Power Pages website","Apps embedded in Teams can be pinned and opened like any other Teams app","Converting the canvas app into a desktop RPA flow","Exporting the app to a standalone mobile store listing"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"With the Power Apps and Teams integration, apps can be added to Teams and pinned to the app bar, so users open them like any other Teams app for quick, in-context access.","source":{"title":"Power Apps and Microsoft Teams integration — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/overview"}},{"id":"gen-26","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A project team wants a flow to be started manually by a member from a message in a Teams chat, turning that message into a tracked task. Which statement about Power Automate and Teams is correct?","options":["Flows cannot be triggered from Teams and only run on a fixed schedule","Teams messages must first be copied into Outlook before any flow can run","Power Automate is unavailable inside Teams and must run only in a browser","Power Automate integrates with Teams so members can trigger and run flows, including from messages, within Teams"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate's Teams integration lets members create and run flows inside Teams, including message actions that turn a chat message into an automated workflow, keeping automation where collaboration happens.","source":{"title":"Use Power Automate flows in Microsoft Teams — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/teams/overview"}},{"id":"gen-27","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An IT lead wants a governed solution where a canvas app captures requests, a flow routes them for approval, and the data is stored centrally, all reachable inside Teams. What does this illustrate about Power Platform?","options":["That only one service can be used per business problem","That Power Platform services cannot share the same data source","That the services work together and with Teams to deliver an end-to-end solution","That building such a solution requires abandoning Microsoft 365"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Extending solutions means combining Power Apps, Power Automate, and Dataverse and surfacing them in Microsoft Teams, so the services work together to solve a business problem end to end.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-28","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A small team wants to try building an app in Microsoft Teams but has no Dataverse for Teams environment yet. What generally happens the first time they create such an app in a team?","options":["A Dataverse for Teams environment is provisioned for that team to hold the app and its data","The app is permanently blocked until an administrator buys premium licenses","The data is stored only in the maker's personal OneDrive with no team access","The app can only be built after migrating the team to on-premises servers"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When a team first creates an app with Power Apps in Teams, a Dataverse for Teams environment is provisioned for that team, giving the app a built-in place to store its data.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-29","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A manager wants automated notifications and approval prompts to reach staff where they already collaborate, rather than in a separate portal. Which approach reflects extending Power Platform with Microsoft 365?","options":["Requiring staff to check a standalone website hourly for updates","Emailing spreadsheets manually to each person for sign-off","Disabling Teams so staff focus only on the flow's run history","Using Power Automate's Teams integration to send messages and approvals directly into Teams"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Extending Power Platform with Microsoft 365 means surfacing automation in Teams, so notifications and approvals appear where people already collaborate instead of in a separate tool.","source":{"title":"Use Power Automate flows in Microsoft Teams — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/teams/overview"}},{"id":"gen-30","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker embedding a canvas app in Teams wants it to respect who is in the team and let members collaborate on the same shared data. Which benefit does embedding apps in Teams provide?","options":["It converts the app into an external, anonymous public site","It brings the app to where teams already communicate and collaborate, alongside their shared context","It removes the app's ability to connect to any data source","It forces every user to install a separate desktop client"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Embedding Power Apps in Teams brings apps into the place where teams already communicate and collaborate, so people use them in context alongside their chats, channels, and shared work.","source":{"title":"Power Apps and Microsoft Teams integration — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/overview"}},{"id":"gen-31","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business analyst is explaining how Power Platform delivers value beyond a single product by pairing with Microsoft 365. Which example best demonstrates this extension?","options":["A flow that reads new SharePoint list items and posts a summary card to a Teams channel","A print-only report that no software can open","A paper form that is filed in a cabinet and never digitized","A calculator app with no connection to organizational data"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Reading SharePoint data and posting to Teams shows Power Platform extending Microsoft 365, using connectors and the Teams integration so services work together across the tools people already use.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-32","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants to distribute an app they built in Teams to other teams and members across the organization once it is proven. Which statement about apps built in Teams is accurate?","options":["Apps built in Teams can never be shared beyond the single team that created them","Apps built in Teams can be shared with colleagues and published to other teams in the organization","Sharing an app built in Teams requires rewriting it entirely in a different tool","Only administrators in Azure can ever open an app built in Teams"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Apps created in Teams with Power Apps can be shared with colleagues and published to other teams, so a solution built for one team can be reused across the organization.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-33","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A support supervisor wants members to raise, view, and respond to Power Automate approval requests without switching applications during the workday. Which Teams surface makes this possible?","options":["A separate email client running in the background","A dedicated on-premises approvals server","An external Power Pages portal for anonymous visitors","The Power Automate (Approvals) experience within Microsoft Teams"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate's approvals integrate into Microsoft Teams, letting members send, view, and respond to approval requests inside Teams, so the workflow stays in the collaboration app.","source":{"title":"Use Power Automate flows in Microsoft Teams — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/teams/overview"}},{"id":"gen-34","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A CIO wants a concise description of what makes Power Platform's integration with Microsoft 365 valuable to the business. Which statement is the best summary?","options":["It requires replacing Microsoft 365 with entirely new applications","It lets organizations extend and connect Microsoft 365 data and experiences with low-code apps, automation, and AI","It restricts makers to using only data created inside Power Platform","It disconnects business data so each tool works on its own copy"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform's value with Microsoft 365 is that it extends and connects existing Microsoft 365 data and experiences using low-code apps, automation, and AI, amplifying tools the organization already owns.","source":{"title":"Microsoft Power Platform documentation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/"}},{"id":"gen-35","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a single Teams-based solution where a canvas app collects field data, a flow notifies the channel when new data arrives, and both use the same team data store. Which platform characteristic enables this?","options":["The Power Platform services integrate with each other and with Teams, sharing the team's Dataverse for Teams data","Each service must maintain its own separate, incompatible copy of the data","Teams cannot host both an app and a flow at the same time","Flows and apps in Teams are prohibited from using the same table"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Teams, Power Apps and Power Automate integrate with each other and share the team's Dataverse for Teams store, so the services work together on the same data within a single solution.","source":{"title":"Create apps in Teams by using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/create-apps-overview"}},{"id":"gen-36","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A frontline team spends most of the day in Microsoft Teams and wants a case-management app available right there, without opening a browser or separate portal. Why is embedding the Power App in Teams the right recommendation?","options":["Because it converts the app into an anonymous public website","Because it disables the app's data connections for security","Because it meets users in the tool they already use all day, reducing context switching","Because it moves the app off Power Platform entirely"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Embedding a Power App in Teams surfaces it in the collaboration tool people already use throughout the day, reducing context switching and driving adoption by meeting users where they work.","source":{"title":"Power Apps and Microsoft Teams integration — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/teams/overview"}},{"id":"gen-37","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team currently tracks projects in a shared Excel workbook but struggles with concurrent edits, no relationships between sheets, and no built-in security. Which Power Platform component is designed to store this business data with a relational structure, rich data types, and role-based security?","options":["Microsoft Dataverse","A SharePoint document library","A canvas app collection","A Power Automate variable"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse securely stores and manages business data in tables with defined columns, relationships, and built-in role-based security, making it a better fit than a spreadsheet for multi-user, relational business data.","source":{"title":"What is Microsoft Dataverse? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-intro"}},{"id":"gen-38","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best captures a key advantage of Dataverse over a traditional relational database for a low-code maker?","options":["It requires writing SQL stored procedures for every table","It has no concept of relationships between tables","It provides built-in security, business logic, and integration with Power Platform without managing database infrastructure","It can only store data as unstructured files"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Unlike a traditional database that a maker must provision and secure themselves, Dataverse is a managed data platform that includes security, business logic, auditing, and native Power Platform integration out of the box.","source":{"title":"What is Microsoft Dataverse? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-intro"}},{"id":"gen-39","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Dataverse terminology, what is a 'table' (formerly called an entity)?","options":["A single screen in a canvas app","A connector that links to an external service","A reusable flow template","A set of rows and columns used to store data about a type of item, such as accounts or contacts"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Dataverse table is a set of rows (records) and columns (fields) that stores data about a specific kind of item, similar to a table in a relational database.","source":{"title":"Tables in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/entity-overview"}},{"id":"gen-40","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to store customer and order data. Dataverse already includes ready-made tables such as Account and Contact. What are these prebuilt tables that ship with Dataverse called?","options":["Custom tables","Virtual tables","Standard tables","Elastic tables"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Standard tables (such as Account and Contact) are included with Dataverse to support common business scenarios, whereas custom tables are ones a maker creates for organization-specific needs.","source":{"title":"Tables in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/entity-overview"}},{"id":"gen-41","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization has a unique data requirement not covered by any existing Dataverse table, so a maker builds a brand-new table to hold that information. What type of table is this?","options":["A standard table","A custom table","A system table","An audit table"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom table is one that a maker creates to meet an organization's specific needs, in contrast to the standard tables that come with Dataverse.","source":{"title":"Tables in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/entity-overview"}},{"id":"gen-42","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a column that forces users to pick from a fixed list of predefined values such as 'New', 'In Progress', and 'Closed'. Which Dataverse column data type should they use?","options":["Text","Choice","Whole number","File"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Choice column presents a predefined set of options for users to select from, ensuring consistent, standardized values rather than free-form text entry.","source":{"title":"Column data types in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-fields"}},{"id":"gen-43","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a Dataverse Order table, a maker needs each order to reference the customer who placed it, so that the order links to a single row in the Contact table. Which column data type creates this reference to another table?","options":["Lookup","Currency","Text area","Autonumber"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Lookup column stores a reference to a row in a related table, creating the relationship that lets an order point to a specific customer record.","source":{"title":"Column data types in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-fields"}},{"id":"gen-44","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs a column to store a monetary amount that respects the environment's base and transaction currencies. Which Dataverse column data type is designed for this?","options":["Whole number","Decimal","Currency","Text"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Currency column type is designed to store monetary values and works with Dataverse currency handling, unlike a plain number or text column.","source":{"title":"Column data types in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-fields"}},{"id":"gen-45","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants users to be able to attach a photo of a product directly to each product record in Dataverse. Which column data type is intended to store images?","options":["An Image column","A URL column","A Choice column","A Whole number column"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse provides an Image column type for storing images within a row, distinct from a File column (arbitrary files) or a URL column (a link).","source":{"title":"Column data types in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-fields"}},{"id":"gen-46","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"One customer account can have many related contacts, but each contact belongs to a single account. Which type of Dataverse table relationship models this?","options":["A many-to-many (N:N) relationship","A one-to-one (1:1) relationship","No relationship is needed","A one-to-many (1:N) relationship"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A one-to-many (1:N) relationship links one row in a table to many rows in another; here one account relates to many contacts while each contact relates to one account.","source":{"title":"Create and edit table relationships — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/create-edit-entity-relationships"}},{"id":"gen-47","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A student can enroll in many courses, and each course can have many students. Which Dataverse relationship type is appropriate for connecting Students and Courses?","options":["One-to-one (1:1)","One-to-many (1:N)","Many-to-many (N:N)","A lookup with cascade delete"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A many-to-many (N:N) relationship lets rows in each table relate to multiple rows in the other, which fits students enrolling in many courses and courses having many students.","source":{"title":"Create and edit table relationships — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/create-edit-entity-relationships"}},{"id":"gen-48","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When configuring a 1:N relationship in Dataverse, a maker sets the behavior so that deleting a parent account also deletes all its related child records. What is this configurable behavior called?","options":["A cascade behavior","A business rule","A choice set","A rollup column"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Cascade behaviors on a relationship define what happens to related rows when an action such as delete, assign, or share occurs on the parent row, for example cascading a delete to child records.","source":{"title":"Create and edit table relationships — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/create-edit-entity-relationships"}},{"id":"gen-49","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to automatically show or hide a field and require a value based on another field's selection, with the logic applying consistently across all apps that use the table—without writing code. Which Dataverse feature should they use?","options":["A Power Automate desktop flow","A DLP policy","A canvas app formula only","A business rule"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Business rules apply validation and logic (such as showing/hiding, setting values, or making fields required) at the Dataverse table level, so the logic runs consistently across all apps without custom code.","source":{"title":"Create a business rule — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-create-business-rule"}},{"id":"gen-50","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business rule in Dataverse can be scoped so it runs for a specific app, all forms, or the entire table. Why is applying business logic at the table level advantageous?","options":["It only works when the app is offline","The logic is enforced consistently across every app and form that uses the table","It permanently deletes the underlying data","It replaces the need for security roles"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Applying a business rule at the table level means the same validation and logic run everywhere the table is used, ensuring consistency rather than duplicating logic in each app.","source":{"title":"Create a business rule — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/data-platform-create-business-rule"}},{"id":"gen-51","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker opens the Power Apps maker portal and describes the table they need in natural language, letting AI generate the table with suggested columns and sample data. Which capability is being used?","options":["Power Fx delegation","The 'Start with Copilot' table creation experience","A DLP connector group","A model-driven app view"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In the Power Apps maker portal, the 'Start with Copilot' experience lets makers describe a table in natural language and have Copilot generate the table structure, columns, and sample data.","source":{"title":"Create and edit tables using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/create-edit-entities-portal"}},{"id":"gen-52","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Where does a maker typically go to create a new custom Dataverse table, add columns, and define its primary column?","options":["The Power Platform admin center capacity page","The Power Apps maker portal (make.powerapps.com) Tables area","The Microsoft 365 admin center","The Power Automate run history"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Makers create and edit Dataverse tables and their columns from the Tables area of the Power Apps maker portal, where they can also define the primary column and relationships.","source":{"title":"Create and edit tables using Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/create-edit-entities-portal"}},{"id":"gen-53","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker has product data in an Excel file and wants to load it into a Dataverse table, with the option to transform the columns before import. Which tool is used to add this data to Dataverse?","options":["A canvas app gallery","A DLP policy","A model-driven form","Power Query (Get data)"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Query lets makers connect to sources such as Excel, SQL, or OData, transform the data, and load it into a Dataverse table, providing a flexible import path.","source":{"title":"Add data to a Dataverse table by using Power Query — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-query/dataflows/add-data-power-query"}},{"id":"gen-54","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Using Power Query to add data to a Dataverse table, a maker can connect to many source types before loading. Which of the following is a supported source in this import experience?","options":["Only CSV files stored on the local desktop","Only other Dataverse tables in the same environment","External sources such as Excel, SQL Server, and OData feeds","Only data typed manually into the table"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Query 'add data' experience supports many external sources—including Excel, SQL Server, and OData feeds—letting makers transform and map columns before loading into Dataverse.","source":{"title":"Add data to a Dataverse table by using Power Query — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-query/dataflows/add-data-power-query"}},{"id":"gen-55","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An administrator wants to prevent makers from combining a corporate SharePoint connector with the public Twitter/X connector in the same app or flow. Which Power Platform governance feature enforces this?","options":["A model-driven app security role","A data loss prevention (DLP) policy","A canvas app sharing setting","An environment backup"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DLP (data) policies classify connectors into Business and Non-Business groups and block flows or apps that mix connectors across those groups, preventing sensitive data from being combined with unapproved services.","source":{"title":"Data policies (DLP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-data-loss-prevention"}},{"id":"gen-56","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Power Platform security model, what serves as the fundamental security and isolation boundary that contains apps, flows, and Dataverse data for a set of users?","options":["An environment","A security role","A solution","A connection reference"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An environment is a container that stores, manages, and shares an organization's data, apps, and flows, and it acts as the boundary that separates apps and controls who can access the resources inside it.","source":{"title":"Environments overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/environments-overview"}},{"id":"gen-57","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A governance team needs a single, unified portal to manage environments, DLP policies, capacity, and tenant settings across the organization. Which portal should they use?","options":["The Power Apps maker portal (make.powerapps.com)","The Microsoft 365 message center","The Power Platform admin center","Power Automate's My flows page"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Platform admin center is the unified portal administrators use to manage environments, data policies, capacity, analytics, and tenant-wide settings.","source":{"title":"Overview of the Power Platform admin center — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/admin-documentation"}},{"id":"gen-58","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Dataverse, how is a user granted the ability to create, read, write, or delete records in a table?","options":["By being added as a co-owner of the app","By being assigned one or more security roles","By turning off the DLP policy","By enabling the audit log"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse uses role-based security: users receive privileges through security roles assigned to them, which define which tables they can access and what actions (create, read, write, delete) they can perform.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-59","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A security role grants a user Read access at the 'Organization' level on the Account table. What does this access level allow?","options":["Read only the records the user personally owns","Read records owned by the user and their team","Read records within the user's business unit only","Read all Account records across the entire organization"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Access levels widen the scope of a privilege; the Organization level is the broadest, granting access to all records regardless of owner or business unit.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-60","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before a user can be granted Dataverse security roles and access data, what must be true according to the Dataverse security model?","options":["The user must be authenticated and have an appropriate license","The user must be a global administrator","The user must own at least one canvas app","The user must disable multifactor authentication"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse security layers authentication and licensing first: users are authenticated through Microsoft Entra ID and must have a license that permits access before security roles govern what they can do.","source":{"title":"Security in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-security"}},{"id":"gen-61","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"By default, every user in a tenant is automatically a member of which environment, which is created for the tenant and shared by all licensed users?","options":["The production environment","The sandbox environment","The default environment","The developer environment"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A single default environment is automatically created for each tenant and shared by all users; every licensed maker can create apps and flows in it unless governance restricts it.","source":{"title":"Environments overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/environments-overview"}},{"id":"gen-62","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants a non-production environment where developers can build and test changes without affecting live data before moving work to production. Which environment type is designed for this?","options":["Default","Sandbox","Developer (only for a single user)","Teams"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Sandbox environments are non-production environments used for development and testing, with features like copy and reset, keeping experimental work isolated from production.","source":{"title":"Environments overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/environments-overview"}},{"id":"gen-63","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When a DLP policy is applied and a connector is placed in the 'Blocked' group, what happens to an existing flow that uses that connector?","options":["The flow continues to run because existing flows are exempt","The flow is deleted from the environment automatically","The flow is suspended and cannot run until it complies with the policy","The connector is moved to the Business group automatically"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Placing a connector in the Blocked group prevents it from being used; non-compliant apps and flows are suspended and cannot run until they conform to the policy.","source":{"title":"Data policies (DLP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-data-loss-prevention"}},{"id":"gen-64","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes the difference between the Business and Non-Business connector groups in a DLP policy?","options":["Connectors in different groups cannot be used together in the same app or flow","Business connectors are always premium and Non-Business are always standard","Only Business-group connectors can be used in production environments","Non-Business connectors are automatically deleted after 30 days"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DLP policies separate connectors into groups (such as Business and Non-Business); connectors from different groups cannot be combined in the same app or flow, which is how data is kept from crossing boundaries.","source":{"title":"Data policies (DLP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-data-loss-prevention"}},{"id":"gen-65","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company must ensure its Power Platform data is stored in a specific geographic region to meet data residency requirements. Which property, set when the environment is created, controls this?","options":["The environment's security role","The environment's region","The environment's DLP policy","The environment's display name"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Each environment is tied to a geographic region chosen at creation, and the data it contains is stored in that region, which is how organizations meet data residency and compliance requirements.","source":{"title":"Environments overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/environments-overview"}},{"id":"gen-66","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which administrator role can create and manage environments, DLP policies, and settings for the entire Power Platform tenant?","options":["Environment Maker","Power Platform administrator","Basic User","App Owner"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Platform administrator role can manage environments, data policies, and tenant-wide settings across the organization from the Power Platform admin center.","source":{"title":"Overview of the Power Platform admin center — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/admin-documentation"}},{"id":"gen-67","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Dataverse security model, what is the purpose of a business unit?","options":["To store the connection strings for premium connectors","To group users and control data access within an organizational hierarchy","To define the color theme of a model-driven app","To schedule automatic environment backups"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Business units are a security grouping that model an organization's structure; they work with security roles and access levels to control which records users can reach based on ownership and hierarchy.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-68","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An administrator wants two users to share access to the same set of records without assigning each of them broad security roles. Which Dataverse concept is designed to grant record access to a group of users?","options":["A team","A connection","A choice column","A canvas gallery"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Teams group users together so that records can be shared with the team and security roles can be assigned to the team, giving all members the associated access.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-69","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which authentication service does Dataverse rely on to verify the identity of users accessing the environment?","options":["Microsoft Entra ID (Azure Active Directory)","A local Windows account database","The public certificate authority chain","Anonymous access by default"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse uses Microsoft Entra ID for authentication, ensuring that users are verified before licensing and security roles determine what data they can access.","source":{"title":"Security in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-security"}},{"id":"gen-70","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is added to an environment with the Environment Maker role but no other roles. What can this user do?","options":["Manage tenant-wide DLP policies","Create apps, flows, and connections in that environment","Delete other environments in the tenant","Assign Power Platform administrator rights to others"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Environment Maker role lets a user create and share apps, flows, and connections within that environment, but it does not grant tenant-level administrative capabilities.","source":{"title":"Environments overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/environments-overview"}},{"id":"gen-71","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization must ensure its Power Platform solutions are usable by people who rely on screen readers and keyboard navigation. Which governance concern does this address?","options":["Data loss prevention","Accessibility","Environment capacity","Connector licensing"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Accessibility is a data privacy and governance concern that ensures apps and sites can be used by people with disabilities, including support for assistive technologies like screen readers and keyboard navigation.","source":{"title":"Security in Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-security"}},{"id":"gen-72","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Where would an administrator go to view analytics and manage the capacity (storage) consumed by Dataverse across the organization's environments?","options":["The Power Apps maker portal","The Power Platform admin center","The individual canvas app settings","The Power Automate template gallery"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Platform admin center provides capacity and analytics pages where administrators monitor Dataverse storage and resource consumption across environments.","source":{"title":"Overview of the Power Platform admin center — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/admin-documentation"}},{"id":"gen-73","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail team wants an app with a highly customized, pixel-perfect screen layout where they can drag controls anywhere and precisely control the look and behavior of each element. Which type of Power Apps app best fits this requirement?","options":["A model-driven app, because it auto-generates its UI","A Power Pages site, because it is external-facing","A canvas app, because it gives full control over screen design and layout","A desktop flow, because it records screen interactions"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps start from a blank canvas and let the maker drag and position controls freely for a pixel-perfect, tailored user experience. Model-driven apps instead generate their layout from the underlying data model.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-74","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is building a complex, data-centric application to manage a case-tracking process with many related Dataverse tables, and wants the app's forms and views to be generated automatically from that data model with minimal layout work. Which app type is the best choice?","options":["A model-driven app","A canvas app","A cloud flow","A Power Pages site"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps are component-focused and generate a responsive UI from the Dataverse data model, making them well suited to complex, process-centric business applications. The maker defines the data and the app composes forms and views.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-75","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to connect an app directly to more than 200 different data sources, including SharePoint, SQL Server, and Excel, and design the interface exactly as they envision it. Which Power Apps app type supports this?","options":["A model-driven app, which only uses Dataverse","A Power Pages site, which only uses templates","A desktop flow, which automates legacy apps","A canvas app, which can connect to hundreds of data sources"],"correct":[3],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps can connect to a wide range of data sources through connectors, letting makers build a tailored UI over data from services such as SharePoint, SQL Server, and Excel.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-76","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes the primary data source used by model-driven apps in Power Apps?","options":["Model-driven apps can only connect to Excel workbooks","Model-driven apps are built on top of Microsoft Dataverse","Model-driven apps require an on-premises SQL Server","Model-driven apps store data only in SharePoint lists"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps are built on Microsoft Dataverse; the app's structure, forms, and views are derived from the tables, columns, and relationships defined there.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-77","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker describes their design approach: \"I start from a blank screen and lay out every control myself, similar to designing a slide in PowerPoint.\" Which Power Apps app type are they describing?","options":["A model-driven app","A Power Pages site","A canvas app","A business process flow"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Building a canvas app is often compared to designing a PowerPoint slide: the maker starts from a blank canvas and arranges controls freely, controlling exactly how the screen looks.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-78","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs an app whose interface automatically adapts and renders responsively across desktop browsers, tablets, and phones without the maker manually designing each layout. Which Power Apps app type provides this behavior by default?","options":["A model-driven app, which produces a responsive UI automatically","A canvas app, which must be manually resized for each device","A desktop flow, which only runs on a single machine","A cloud flow, which has no user interface"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps generate a responsive user interface that adapts across devices automatically, because the layout is composed from the data model rather than hand-designed screen by screen.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-79","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team is deciding between the two main types of Power Apps. Which description correctly pairs each app type with its design approach?","options":["Canvas apps are data-model driven; model-driven apps are design-first","Both canvas and model-driven apps require writing traditional code","Canvas and model-driven apps are identical except for their name","Canvas apps are design-first (UI-centric); model-driven apps are data-model driven (component-focused)"],"correct":[3],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps begin with the user interface and give makers full design control, while model-driven apps begin with the Dataverse data model and compose the UI from components. Both are low-code approaches.","source":{"title":"Start building apps with Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/"}},{"id":"gen-80","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is a core feature that model-driven apps automatically provide based on the Dataverse tables they are built on?","options":["Pixel-level control over the position of every control on a screen","Forms and views generated from the data model","The ability to connect to over 200 non-Dataverse connectors as the primary source","A blank canvas with no predefined layout"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps are made up of components such as forms and views that are generated from the underlying Dataverse tables, columns, and relationships, rather than hand-placed by the maker.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-81","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to build a simple, purpose-built app for field technicians to log inspections, with a custom-branded look and a photo-capture screen tailored to their workflow. Which Power Apps app type is the most appropriate?","options":["A model-driven app, because branding cannot be customized elsewhere","A Power Pages site, because it is meant for internal staff","A canvas app, because it allows a tailored, branded task-specific UI","A desktop flow, because it captures screen images"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps are ideal for task- or role-specific scenarios where a tailored, branded user experience matters, such as a field inspection app with a custom layout and device features like the camera.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-82","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about the relationship between Power Apps app types and coding is correct?","options":["Both canvas and model-driven apps are low-code/no-code approaches","Canvas apps require C# while model-driven apps require Java","Only model-driven apps can be built without professional developers","Neither app type can be built without writing traditional code"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Apps is a low-code platform; both canvas and model-driven apps let makers build business apps quickly with little or no traditional code.","source":{"title":"Start building apps with Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/"}},{"id":"gen-83","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business analyst is designing a customer-service application that heavily relies on Dataverse tables, needs standardized data-entry forms, list views, dashboards, and a consistent navigation experience for many users. Which app type is best suited?","options":["A canvas app, because each form must be designed manually","A desktop flow, because it runs unattended","A cloud flow, because it needs no user interface","A model-driven app, because it provides forms, views, and dashboards over Dataverse"],"correct":[3],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps are well suited to data-heavy business processes, providing forms, views, charts, and dashboards over Dataverse with a consistent navigation model for many users.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-84","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to use Copilot to help generate an app and its underlying tables simply by describing what they need in natural language. Where in Power Apps does this low-code, AI-assisted app-building capability fit?","options":["It is exclusive to desktop flows in Power Automate","Copilot is part of the Power Apps maker experience for building apps","It is only available in Power Pages, not Power Apps","AI assistance was removed from Power Apps entirely"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Apps maker experience includes Copilot, which helps makers build apps and data using natural-language descriptions as part of the low-code platform.","source":{"title":"Start building apps with Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/"}},{"id":"gen-85","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs an app that can use device capabilities such as the camera, GPS location, and barcode scanner within a custom-designed mobile interface. Which Power Apps app type is designed for this kind of tailored, device-aware experience?","options":["A model-driven app, because it is optimized for mobile hardware","A business process flow, because it guides users through stages","A canvas app, because it supports device features in a custom UI","A Power Pages site, because it runs in a public browser"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps can incorporate device capabilities like the camera, GPS, and barcode scanner within a fully custom-designed screen layout, making them ideal for tailored mobile scenarios.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-86","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following best describes a key characteristic of model-driven app design?","options":["The app's components and layout are driven by the underlying data model","The maker must position every control manually on a blank screen","The app can only be viewed on a single desktop computer","The app cannot include views, forms, or dashboards"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In model-driven design the app is composed from components tied to the Dataverse data model; the maker focuses on the data and business logic while the app generates much of the UI.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-87","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is starting in the Power Apps maker portal and wants to understand the main components available for building solutions. Which of the following are the two primary types of apps they can create in Power Apps?","options":["Desktop flows and cloud flows","Power Pages sites and dashboards","Business process flows and connectors","Canvas apps and model-driven apps"],"correct":[3],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Apps lets makers build two primary types of apps — canvas apps and model-driven apps — each suited to different scenarios, alongside supporting components like Dataverse and Copilot.","source":{"title":"Start building apps with Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/"}},{"id":"gen-88","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company wants a single app where the user experience is generated consistently from Dataverse and where adding a new table automatically makes standardized forms and views available. Which characteristic of model-driven apps supports this?","options":["Their layout must be hand-built for every table","Their UI is component-driven and generated from the data model","They can only display one record at a time with no views","They require the maker to write responsive-design code"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Because model-driven apps are component-focused and derive their UI from the data model, standardized forms and views come from the Dataverse tables, giving a consistent experience with less manual design.","source":{"title":"Overview of building a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/model-driven-app-overview"}},{"id":"gen-89","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker prioritizes complete creative control over the app's appearance and is willing to design each screen individually to match a specific brand and workflow. Which Power Apps app type aligns with prioritizing UI design over data-model structure?","options":["A model-driven app","A Power Automate cloud flow","A canvas app","A Dataverse business rule"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps are design-first: the maker controls the layout and appearance of each screen, making them the right choice when tailored UI and branding take priority over an auto-generated, data-driven layout.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-90","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which scenario is the strongest fit for choosing a canvas app rather than a model-driven app?","options":["A task-specific app with a highly customized, branded interface over Excel and SharePoint data","A large case-management system built entirely on many related Dataverse tables","An app that should auto-generate all its forms and views from the data model","An enterprise app needing consistent, standardized navigation across dozens of tables"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas apps shine for task- or role-specific apps with a customized, branded UI over varied data sources; the other scenarios describe data-model-driven needs that model-driven apps handle better.","source":{"title":"Complete guide to building canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/getting-started"}},{"id":"gen-91","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is building a canvas app and wants to display a scrolling list of all product records from a SharePoint list so users can browse them on screen. Which control should the maker add?","options":["A Gallery","A Label","A Button","A Text input"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Gallery control shows a scrolling list of multiple records from a data source, making it the right choice for browsing many product records. A Label shows a single value, not a list.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-92","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app currently connects to a SharePoint list. The finance team asks the maker to also pull data from an Azure SQL database into the same app. What licensing consideration applies?","options":["SharePoint is premium, so no additional license is needed for SQL","Canvas apps cannot use more than one data source at a time","SQL Server is a premium connector and requires a premium Power Apps license","Both connectors are standard, so no license change is required"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SharePoint is a standard connector, but SQL Server is a premium connector that requires a premium Power Apps license. A single app can combine multiple data sources.","source":{"title":"Add data connections to canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/add-data-connection"}},{"id":"gen-93","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Power Apps, what is the difference between a connector and a connection?","options":["A connector is one authenticated instance; a connection is the reusable service definition","A connector is the reusable bridge to a service; a connection is a specific authenticated instance of it","A connector and a connection are two names for the same thing","A connector stores data locally; a connection uploads it to the cloud"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A connector is the reusable definition of how to communicate with a service, while a connection is a specific authenticated instance of that connector for a particular account or resource.","source":{"title":"Add data connections to canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/add-data-connection"}},{"id":"gen-94","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a button in a canvas app to save the changes a user made on an Edit form back to the data source. Which function should the button's OnSelect property call?","options":["Navigate","Filter","Collect","SubmitForm"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SubmitForm saves the values entered in a Form control back to the data source. Navigate only changes screens, and Filter/Collect do not submit a form's record.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-95","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs a canvas app screen that shows and lets users edit all the fields of a single selected customer record. Which control is designed for this?","options":["An Edit form control","A Gallery control","A horizontal container","A Label control"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Form control (Edit form) displays and edits the fields of a single record and can save it with SubmitForm. A Gallery shows a list of many records rather than one record's fields.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-96","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Managers will use a canvas app on both phones and a wide desktop browser and want the layout to adapt to each screen size. What should the maker do to make the app responsive?","options":["Duplicate the app once for phones and once for desktops","Turn off Scale to fit and use containers with Parent.Width-relative sizing","Set every control to a fixed pixel position and size","Leave Scale to fit on and lock the aspect ratio"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Responsive canvas layouts are built by turning off Scale to fit in Display settings and sizing controls relative to Parent.Width/Parent.Height, typically using containers, so the layout reflows across form factors.","source":{"title":"Create responsive layouts in canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-responsive-layout"}},{"id":"gen-97","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker shares a canvas app with two colleagues who need to continue building and editing it alongside the maker. Which sharing role should they receive?","options":["User","Environment Maker only","Co-owner","Viewer"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Co-owner can run and edit the app (but cannot delete it or change its owner), which fits colleagues who will keep building it. A User can only run the app.","source":{"title":"Share a canvas app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/share-app"}},{"id":"gen-98","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After a maker shares a canvas app that reads from a Dataverse table with a group of users, several users can open the app but see no data. What is the most likely reason?","options":["Sharing the app automatically grants all needed data permissions","Canvas apps cannot use Dataverse as a data source","The app must be re-published before any user can open it","The users lack access to the underlying data source, such as the required Dataverse security role"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Sharing a canvas app does not grant access to its data. Users still need permission to the underlying source, and Dataverse-backed apps require the appropriate security role.","source":{"title":"Share a canvas app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/share-app"}},{"id":"gen-99","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants end users to be able to ask questions in natural language about the app's data and get grounded answers directly inside the running canvas app. What should the maker add?","options":["A Copilot control on the canvas app","A desktop flow triggered by a button","A second Gallery bound to the same data","A Power Pages site linked from the app"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Copilot control can be added to a canvas app so end users ask natural-language questions about the app's data and receive grounded answers, acting as a low-code in-app AI assistant.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-100","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker adds several controls to a screen and wants them to automatically arrange in a row and reflow as the screen width changes. Which building block should the maker use?","options":["A collection variable","A horizontal container","A drop-down control","A business rule"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A horizontal container automatically arranges its child controls in a row and, using properties like FillPortions and layout alignment, lets them resize and reflow responsively as the screen changes.","source":{"title":"Create responsive layouts in canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-responsive-layout"}},{"id":"gen-101","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Where does a maker go to add a new data source, such as a SharePoint list, to a canvas app in the studio?","options":["The Insert menu's Media category","The formula bar's Text property","The Data pane on the left","The Power Platform admin center"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data sources are added from the Data pane on the left side of the canvas app studio, where the maker selects a connector and creates or picks a connection.","source":{"title":"Add data connections to canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/add-data-connection"}},{"id":"gen-102","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is an example of a standard connector that generally does not require a premium Power Apps license?","options":["Azure SQL Server","Microsoft Dataverse","A custom connector","SharePoint"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SharePoint and Office 365 Outlook are standard connectors included with most plans, whereas SQL Server, Dataverse, and custom connectors are premium and require a premium license.","source":{"title":"Add data connections to canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/add-data-connection"}},{"id":"gen-103","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants users to select a value from a fixed list of choices, such as a status, without typing free text. Which control best fits this need?","options":["A Drop down control","A Label control","An Image control","A Gallery control"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Drop down (or Combo box) control lets a user pick from a list of choices, which is ideal for selecting a status value rather than typing free text into a Text input.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-104","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants two child controls inside a horizontal container to split the available width so one takes twice as much space as the other. Which property controls this proportional sizing?","options":["OnSelect","Visible","FillPortions","Default"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"FillPortions determines how child controls share the remaining space in a container proportionally, so setting one child to 2 and another to 1 gives the first twice the width.","source":{"title":"Create responsive layouts in canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-responsive-layout"}},{"id":"gen-105","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to build and edit a canvas app by describing what they need in natural language while working in the Power Apps studio. Which capability supports this?","options":["Copilot in the studio, the maker-side assistant","The Power Platform admin center DLP page","A scheduled cloud flow trigger","The Scale to fit display setting"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot in the studio is the maker-side assistant that helps build and edit a canvas app through natural-language conversation, distinct from the in-app Copilot control used by end users.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-106","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker sets a control's Text, Fill, and Visible properties in a canvas app. What language do they use to write these property expressions?","options":["SQL stored procedures","Python scripts","C# code-behind","Power Fx formulas"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Control properties such as Text, Fill, Visible, OnSelect, and Items are set with Power Fx formulas in the formula bar, the low-code, Excel-like language of canvas apps.","source":{"title":"Create a canvas app based on Excel data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/get-started-create-from-blank"}},{"id":"gen-107","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to share a canvas app so that a large group of staff can only run it, while ensuring the shared users can also see the data. Which approach is correct?","options":["Share the app as User and ensure those users also have access to the underlying data sources","Share the app as Co-owner so they cannot accidentally edit it","Sharing the app is enough because it always includes data access","Export the app as a file and email it to each staff member"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Add run-only staff as Users when sharing, and remember that sharing the app does not grant data access, so those users must also have permission to the underlying data sources.","source":{"title":"Share a canvas app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/share-app"}},{"id":"gen-108","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker turns off Scale to fit and now wants a control's width to always equal half of its parent screen's width, regardless of device. Which expression approach fits a responsive design?","options":["Set the Width to a fixed value of 640 pixels","Set the Width relative to Parent.Width, for example Parent.Width/2","Leave Scale to fit on and ignore the Width property","Set the Width to the App.ActiveScreen name"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Responsive sizing uses formulas relative to Parent.Width/Parent.Height rather than fixed pixels, so a Width of Parent.Width/2 keeps the control at half the parent width across devices.","source":{"title":"Create responsive layouts in canvas apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-responsive-layout"}},{"id":"gen-109","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker has just created several Dataverse tables for tracking service requests and wants to turn them into a working model-driven app as quickly as possible. What is the recommended starting point for building the app?","options":["Write custom C# plug-in code to render the tables","Design each screen manually on a blank canvas","Create a model-driven app and add the existing Dataverse tables to it","Export the tables to Excel and build the app from the workbook"],"correct":[2],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven apps are built from Dataverse tables; the maker creates the app and adds tables (as pages), and Power Apps generates the forms and views automatically.","source":{"title":"Build your first model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/build-first-model-driven-app"}},{"id":"gen-110","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After adding a table to a model-driven app, a maker must make the app usable before others can open it. Which action makes the changes to the app available to users?","options":["Publishing the app","Exporting the app to a solution file","Sharing the app's Dataverse connection string","Deleting and recreating the underlying table"],"correct":[0],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In the model-driven app designer, the maker saves and then publishes the app so that the latest changes become available to users who run it.","source":{"title":"Build your first model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/build-first-model-driven-app"}},{"id":"gen-111","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants users to see and edit the full set of fields for a customer record on the primary editing surface of a model-driven app. Which type of form should they configure?","options":["A card form","A quick view form","A quick create form","The main form"],"correct":[3],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The main form is the primary form used to create, view, and edit a table's records in a model-driven app, showing the full layout of fields, tabs, and sections.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-112","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a model-driven app, a user wants to quickly enter a new contact by filling in only a few essential fields in a small pop-up dialog, without opening the entire record. Which form type provides this experience?","options":["A main form","A quick create form","A quick view form","A card form"],"correct":[1],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A quick create form gives a streamlined data-entry experience for adding a new record with only key fields, opening as a flyout so users can create records fast.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-113","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to display selected read-only fields from a related account record directly inside the contact form, so users can see the parent company's details without navigating away. Which form type is designed for this?","options":["A main form","A quick create form","A quick view form","A public view"],"correct":[2],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A quick view form shows read-only information from a related (parent) record embedded within another table's main form, so users see related data in context.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-114","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is editing a main form and wants to add a field so users can enter it. In the form designer, how are fields typically placed onto the form?","options":["By dragging a column from the table columns pane onto a section of the form","By writing a SQL INSERT statement in the form properties","By emailing an administrator to add the field for them","By recording a desktop flow that types the field name"],"correct":[0],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In the model-driven form designer, makers drag columns from the table's columns pane onto sections of the form to add fields, then save and publish.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-115","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to control which columns appear as sortable, filterable list columns when users browse records in a model-driven app grid. Which app component defines this list layout?","options":["A business rule","A quick create form","A card form","A view"],"correct":[3],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Views define the columns, sort order, and filter criteria used to display a list of a table's records in a model-driven app grid.","source":{"title":"Create or edit a view — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-edit-views"}},{"id":"gen-116","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A single user creates a custom view to filter their own list of open tasks, but this view should not appear for anyone else. Which type of view did they create?","options":["A system view","A personal view","A public view","A quick view form"],"correct":[1],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Personal views are created by an individual user (for example through advanced find or by saving filters) and are visible only to that user unless they choose to share them.","source":{"title":"Create or edit a view — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-edit-views"}},{"id":"gen-117","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to define a view that any user of the app can select from the view drop-down when looking at a table's records. Which kind of view should the maker create in the app designer?","options":["A quick create form shared with everyone","A personal view saved by each user individually","A public view available to all app users","A card form pinned to the dashboard"],"correct":[2],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Public views are system views that makers create and that all users can select from the view selector; they are part of the app and can be customized by makers.","source":{"title":"Create or edit a view — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-edit-views"}},{"id":"gen-118","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to change an existing public view so that records are sorted by due date and a new priority column is shown. Where do they make these changes?","options":["In the view designer, by editing the view's columns, sort, and filter settings","By editing the raw JSON of the Dataverse database directly","By recreating the entire table from scratch","By sharing the app with a co-owner and asking them to retype the data"],"correct":[0],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Views are edited in the view designer, where makers add or remove columns, set the sort order, and configure filter criteria, then save and publish.","source":{"title":"Create or edit a view — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-edit-views"}},{"id":"gen-119","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker has finished a model-driven app and wants a colleague to use it. Besides sharing the app itself, what must the colleague also have so they can actually open the app and work with its data?","options":["A personal view saved on the colleague's device","A separate canvas app embedded in the model-driven app","A copy of the app exported to their local computer","An appropriate security role that grants access to the app and its tables"],"correct":[3],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Sharing a model-driven app is role-based: users need a security role that grants access to the app and to the Dataverse tables it uses, otherwise they cannot open it or see data.","source":{"title":"Share a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/share-model-driven-app"}},{"id":"gen-120","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When sharing a model-driven app, a maker assigns users to security roles. What is the main purpose of using security roles in this sharing process?","options":["To change the visual theme colors of the app","To control access to the app and the level of access to its data","To convert the app into a Power Pages site","To schedule the app to run automatically each night"],"correct":[1],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven app access is governed by Dataverse security roles, which determine both whether a user can open the app and what level of access they have to its records.","source":{"title":"Share a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/share-model-driven-app"}},{"id":"gen-121","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is building a model-driven app in the app designer and adds a table as a page. Which components are automatically associated with that table page for users to interact with the records?","options":["Only a single static screenshot of the data","A desktop flow and a cloud flow","Forms and views for the table","A Power Pages template and a web role"],"correct":[2],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When a table is added to a model-driven app, its forms and views come along as part of the app, giving users a way to view lists of records and open individual records.","source":{"title":"Build your first model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/build-first-model-driven-app"}},{"id":"gen-122","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a compact form layout used to represent a record as a tile or in a list-style display within a model-driven app. Which form type is intended for this compact, at-a-glance representation?","options":["A card form","A main form","A public view","A quick create form"],"correct":[0],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A card form provides a compact, condensed layout for a record, useful for representing records as cards or tiles rather than the full main form.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-123","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants records in a model-driven app grid to show only accounts located in a specific region. Which part of the view configuration should they use to achieve this?","options":["The sharing dialog of the app","The card form layout","The quick create form fields","The view's filter criteria"],"correct":[3],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A view's filter criteria determine which records appear in the grid; configuring the filter to a region limits the list to matching records.","source":{"title":"Create or edit a view — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-edit-views"}},{"id":"gen-124","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker opens the model-driven app designer to assemble an app. In addition to tables, forms, and views, what element can they configure to control how users move between the app's areas and tables?","options":["The Dataverse connection password","The app's navigation (site map)","The Power Automate desktop recorder","The tenant-wide DLP policy"],"correct":[1],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The app's navigation, defined by the site map, organizes areas, groups, and table pages so users can move through the model-driven app; makers configure it in the app designer.","source":{"title":"Build your first model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/build-first-model-driven-app"}},{"id":"gen-125","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to design the arrangement of tabs, sections, and fields that users see when opening a record for full editing. Which designer do they use?","options":["The view designer","The Power Pages design studio","The form designer","The DLP policy editor"],"correct":[2],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The form designer is used to build and modify main forms, arranging tabs, sections, and fields that determine how users create and edit records in a model-driven app.","source":{"title":"Create and design model-driven app forms — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/create-design-forms"}},{"id":"gen-126","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company wants different groups of users to have different levels of access to the same model-driven app — some able to edit all records and others only their own. What is the correct way to accomplish this when sharing the app?","options":["Create a separate canvas app for each group","Export the app once for each access level","Give everyone the System Administrator role for simplicity","Assign users to different security roles that define their record access levels"],"correct":[3],"skill":3,"sub":"3.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Because model-driven app access is role-based, assigning users to different Dataverse security roles lets you grant each group the appropriate level of access to records when the app is shared.","source":{"title":"Share a model-driven app — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/model-driven-apps/share-model-driven-app"}},{"id":"gen-127","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to automate a repetitive task on a legacy Windows accounting application that has no API and can only be operated through its user interface. Which type of Power Automate flow is designed for this scenario?","options":["A scheduled cloud flow that calls a premium connector","An automated cloud flow triggered by a Dataverse event","A desktop flow that uses robotic process automation (RPA)","An instant cloud flow started from a button in the mobile app"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Desktop flows use robotic process automation to automate web and desktop applications by driving their user interface, which is the right approach for legacy apps that expose no connector or API.","source":{"title":"Introduction to desktop flows — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/desktop-flows/introduction"}},{"id":"gen-128","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants to build an automation that runs entirely online, connecting cloud services such as SharePoint and Outlook without needing anything installed on a local machine. Which Power Automate flow type fits this requirement?","options":["Cloud flow","Desktop flow","Attended RPA flow","Unattended RPA flow"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Cloud flows run in the cloud and connect online services through connectors, requiring no local software, unlike desktop flows which run on a machine to automate its UI.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-129","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business analyst wants to discover where delays and inefficiencies occur in the company's actual order-to-cash process by analyzing event data from its systems. Which Power Automate capability should they use?","options":["A scheduled cloud flow that emails a daily summary","A desktop flow recorder that captures UI clicks","A cloud flow template for approvals","Process mining"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Process mining analyzes real process data from your systems to visualize how processes actually run and to identify bottlenecks and inefficiencies for improvement.","source":{"title":"Overview of process mining — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/process-mining-overview"}},{"id":"gen-130","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker is new to Power Automate and wants to create a common automation, such as saving email attachments to SharePoint, without building every step from scratch. What is the fastest starting point?","options":["Write the flow definition in JSON and import it","Start from a prebuilt cloud flow template","Record the steps with Power Automate for desktop","Deploy an unattended desktop flow on a virtual machine"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Templates are prebuilt flows for common scenarios that let makers start quickly and customize, rather than building an automation from a blank canvas.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-131","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a cloud flow, a component defines the event that causes the flow to start running—for example, when a new item is created in a list. What is this component called?","options":["An action","A connection reference","A trigger","An environment variable"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A trigger is the event that starts a flow, while actions are the tasks the flow performs after it is triggered.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-132","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to record their own mouse clicks and keystrokes in a desktop application so Power Automate can replay them later. Which application should they use to build this automation?","options":["Power Automate for desktop","The Power Apps model-driven designer","The Power Pages design studio","The Power BI service"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate for desktop is the application used to create and run desktop flows, including recording interactions with desktop and web applications.","source":{"title":"Introduction to desktop flows — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/desktop-flows/introduction"}},{"id":"gen-133","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company must repeat a set of actions for every row returned from a data source, applying the same steps to each record. Which flow construct handles this?","options":["A parallel branch","A trigger condition","A connection reference","A loop"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Loops repeat a set of actions for each item in a collection, letting a flow process multiple records with the same logic.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-134","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An HR manager wants a flow that automatically routes new time-off requests to a supervisor for review and records whether they said yes or no. Which common cloud flow use case does this represent?","options":["Process mining analysis","Approvals","Robotic process automation","Screen scraping"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Approvals is a common cloud flow use case in which a flow requests a decision from a person and continues based on the approve or reject response.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-135","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A desktop flow must run on a server overnight with no one signed in to interact with it. Which mode of running a desktop flow supports this?","options":["Attended mode, where a user must be present","Instant mode, started from a mobile button","Unattended mode, running without a signed-in user","Scheduled cloud flow recurrence"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Desktop flows can run unattended, executing on a machine without a user present, which suits after-hours batch automation.","source":{"title":"Introduction to desktop flows — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/desktop-flows/introduction"}},{"id":"gen-136","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a flow to send different follow-up messages depending on whether an order total is above or below a threshold. Which flow construct evaluates a condition and directs the flow down one path or another?","options":["Branching (a condition)","A recurrence trigger","A connector reference","A gateway installation"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Branching, implemented with a condition, evaluates whether something is true and runs different actions on each path, enabling decision logic in a flow.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-137","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker on the go wants to create, edit, and manually trigger flows from an iPhone. Which part of the Power Automate product experience supports this?","options":["The Power Automate desktop console only","The process mining workspace","The Dataverse table designer","The Power Automate mobile app"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate is available as a mobile app that lets users create, manage, and manually run flows such as instant flows from a phone or tablet.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-138","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After a cloud flow is triggered, it performs a series of tasks such as creating a record and sending an email. What are these individual tasks called?","options":["Triggers","Actions","Environments","Templates"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Actions are the operations a flow carries out after its trigger fires, such as creating records, sending mail, or updating a file.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-139","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A finance team wants to automate extracting invoice numbers and totals from scanned PDF invoices and posting them into a system. This document-automation scenario is a common use case for which Power Automate capability?","options":["Process mining of event logs","Modifying a model-driven app view","Cloud flows (often combined with document processing)","Styling a Power Pages theme"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Document automation—extracting data from documents and routing it into business systems—is a common cloud flow use case for Power Automate.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-140","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team lead wants a channel notification posted automatically whenever a new response is submitted to a Microsoft Forms survey. Which Power Automate flow type best fits automating this cross-service scenario?","options":["An automated cloud flow","A desktop flow in attended mode","A process mining report","A manually recorded UI flow"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An automated cloud flow starts on an event, such as a new Forms response, and can post to Teams, making it ideal for connecting online services without manual intervention.","source":{"title":"What is Power Automate? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/flow-types"}},{"id":"gen-141","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best distinguishes desktop flows from cloud flows in Power Automate?","options":["Desktop flows can only be triggered on a schedule","Desktop flows require no software and run entirely online","Cloud flows automate application user interfaces through RPA","Desktop flows automate tasks by controlling an application's user interface on a machine"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Desktop flows use RPA to automate by interacting with an application's user interface on a machine, whereas cloud flows run in the cloud and use connectors to online services.","source":{"title":"Introduction to desktop flows — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/desktop-flows/introduction"}},{"id":"gen-142","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A desktop flow author is assembling the automation from prebuilt building blocks such as 'Launch Excel', 'Click UI element', and 'Send keys'. What are these building blocks called?","options":["Connectors","Desktop flow actions","Cloud flow triggers","Dataverse tables"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Desktop flows are built from actions—the individual operations like launching apps or clicking UI elements—that Power Automate for desktop provides.","source":{"title":"Introduction to desktop flows — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/desktop-flows/introduction"}},{"id":"gen-143","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An operations manager reviews a process mining report and sees the most common path an order takes through the company's systems, along with where cases wait longest. What is the primary purpose of process mining in Power Automate?","options":["To analyze how processes actually run and identify opportunities to improve them","To record a user's clicks in a desktop application for later replay","To share a canvas app with external users","To schedule a cloud flow to recur every night"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Process mining uses real event data to reveal how processes actually operate, helping organizations spot bottlenecks and inefficiencies and target automation.","source":{"title":"Overview of process mining — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/process-mining-overview"}},{"id":"gen-144","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a flow that automatically creates a task whenever a new email arrives in a shared mailbox, with no one needing to start it. Which type of trigger should the flow use?","options":["An instant (manual) trigger started from a button","A scheduled trigger set to a recurrence","An automated trigger that fires on a connector event","A desktop flow trigger that records UI steps"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An automated cloud flow runs on its own when an event occurs in a connected service, such as a new email arriving, so no manual start is needed.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-145","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team needs a summary report emailed every weekday at 8:00 A.M. with nobody pressing a button. Which trigger type fits this requirement?","options":["A scheduled flow using the Recurrence trigger","An instant flow started from the mobile app","An automated flow triggered by a new SharePoint item","An instant flow started from a Power Apps button"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A scheduled cloud flow uses the Recurrence trigger, which you configure with a frequency and start time so it runs on its own at set intervals.","source":{"title":"Run a cloud flow on a schedule — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/run-scheduled-tasks"}},{"id":"gen-146","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A manager wants to send a standard status message to a Teams channel only when she decides to, directly from her phone. Which trigger type should the flow use?","options":["An automated trigger that fires on a Dataverse event","An instant (manual) trigger she starts with a button","A scheduled trigger that runs hourly","A desktop flow triggered by an application window"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An instant (manual) flow is started on demand by a person, for example by tapping a button in the Power Automate mobile app, which matches running it only when she chooses.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-147","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When building a cloud flow, a maker adds several steps but the designer will not let them save. Every cloud flow must contain at minimum which of the following?","options":["Two triggers running in parallel","A trigger and a condition control","A premium connector and a gateway","One trigger plus at least one action"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Every cloud flow begins with a single trigger that determines when it runs, followed by one or more actions that define what it does.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-148","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker who is unsure how to wire up steps wants to type \"when a new response comes into my Form, add a row to a spreadsheet and email me\" and have the flow assembled automatically. What should they use?","options":["The flow checker in the command bar","A shared solution imported from another environment","Copilot on the Power Automate home page","The 28-day run history view"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot's \"describe it to design it\" experience lets a maker describe a flow in plain language, and it proposes the trigger and actions already wired up for review.","source":{"title":"Create your first cloud flow using Copilot — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/create-cloud-flow-using-copilot"}},{"id":"gen-149","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A scheduled flow that saves email attachments has been failing since yesterday, and you need to find which step broke. Where should you look first?","options":["The flow's 28-day run history","The connector reference documentation","The Data loss prevention policy list","The environment's audit log in the admin center"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 28-day run history lists every run with its status and lets you drill into a failed run's step-by-step view to see exactly which action errored.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-150","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A flow owner wants a colleague to be able to edit the flow, manage its connections, and view its run history. Which sharing option grants that level of access?","options":["Adding the colleague as a run-only user","Adding the colleague as a co-owner","Sharing the flow's connection reference only","Exporting the flow as a template"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A co-owner can edit, manage, and delete the flow and see its run history, which is how teams avoid a flow being locked to a single person.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-151","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"While configuring a Recurrence trigger for a scheduled flow, which settings does the maker specify to control how often it runs?","options":["A connector event and a filter query","A button label and an icon color","A security role and a business unit","A frequency and interval, with an optional start time and time zone"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Recurrence trigger is configured with a frequency and interval (for example every 1 day) plus an optional start time and time zone to control when and how often the flow runs.","source":{"title":"Run a cloud flow on a schedule — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/run-scheduled-tasks"}},{"id":"gen-152","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to try a newly built instant flow and watch each step's inputs and outputs as it runs, before relying on it. Which feature should they use?","options":["The DLP policy simulator","The solution checker","The Test option in the flow designer","The connector's throttling report"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Test mode runs the flow while showing each step's inputs and outputs, letting the maker verify the logic works before depending on it.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-153","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a cloud flow, a maker wants an email action to include the title of the SharePoint item that triggered the flow. How does the maker reference that value?","options":["By inserting dynamic content from the trigger step","By writing a DLP exception rule","By adding a second trigger to the flow","By sharing the flow as a run-only user"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dynamic content lets an action reuse outputs from earlier steps, such as the trigger's item title, so the value flows forward through the flow.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-154","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker has an existing flow and wants to ask, in plain language, to add a notification step and change a condition without manually dragging actions. What lets them do this?","options":["The 28-day run history","Copilot in the flow designer side pane","The flow checker","A run-only sharing link"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot can edit an existing flow conversationally from the designer side pane, adding steps, changing conditions, or explaining what the flow does, with the maker confirming the changes.","source":{"title":"Create your first cloud flow using Copilot — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/create-cloud-flow-using-copilot"}},{"id":"gen-155","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After a flow run fails because a connection had expired, the maker fixes the connection and wants to run that same failed instance again from its run history. What action does this?","options":["Delete the flow and rebuild it from a template","Change the trigger from automated to scheduled","Turn the flow off and back on","Resubmit the failed run"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"From the run history you can select a failed run, read the error, fix the action or connection, and resubmit the run to process it again.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-156","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to start from a prebuilt flow that already has the trigger and common actions in place, then customize it, instead of building from an empty designer. What should they choose?","options":["A data loss prevention policy","A model-driven app form","A flow template","A run-only user link"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Templates provide a prebuilt flow with the trigger and actions already arranged, which the maker can customize rather than starting from a blank flow.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-157","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker uses Copilot to generate a flow from a description. Before the flow can run successfully, what must the maker still do?","options":["Authenticate the connections and confirm the logic","Convert the cloud flow into a desktop flow","Assign a Dataverse security role to the flow","Publish the flow to a Power Pages site"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot drafts the flow, but the maker still needs to sign in to and confirm the connections and verify the logic before the flow will run.","source":{"title":"Create your first cloud flow using Copilot — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/create-cloud-flow-using-copilot"}},{"id":"gen-158","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants coworkers to be able to press the button and run an instant flow, but not to change any of its steps. Which sharing choice fits?","options":["Add them as co-owners of the flow","Share the flow as run-only users","Give them the System Administrator role","Export the flow to a managed solution"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For instant flows, sharing with run-only users lets people run the flow, such as pressing its button, without being able to edit it.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-159","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants a flow to run once every 15 minutes throughout the day to poll an external system. Which trigger and configuration supports this?","options":["An instant trigger with a button in Teams","An automated trigger on a new email","A manual trigger from the mobile app","A Recurrence trigger with a frequency of minutes and an interval of 15"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A scheduled flow's Recurrence trigger can be set to a frequency of minutes with an interval of 15 so it runs every quarter hour on its own.","source":{"title":"Run a cloud flow on a schedule — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/run-scheduled-tasks"}},{"id":"gen-160","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before saving a flow, a maker wants Power Automate to point out errors and warnings, such as a required action input that is missing. Which tool reports these?","options":["The Data loss prevention policy","The environment admin center","The flow checker","The 28-day run history"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The flow checker inspects the flow for errors and warnings, such as missing required inputs, before you save so issues can be fixed early.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-161","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the run history of an automated flow, which set of statuses might the maker see next to individual runs?","options":["Succeeded, Failed, or Running","Draft, Published, or Retired","Public, Personal, or System","Import, Export, or Merge"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 28-day run history shows each run with a status such as Succeeded, Failed, or Running, and selecting one reveals the step-by-step detail.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-162","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A regional government agency wants to let citizens securely submit permit applications and check their status through a public-facing website built with low-code tools. Which Power Platform service is designed for this external-facing scenario?","options":["Power Pages","Power Automate","A model-driven Power App shared internally","Copilot Studio"],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is the low-code service for building secure, enterprise-grade, external-facing business websites where customers and constituents can interact with an organization's data.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-163","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes where the data shown on and collected by a Power Pages site is stored?","options":["In a local SharePoint list unique to each visitor","Only in browser cookies on the visitor's device","In Microsoft Dataverse, which the site reads from and writes to","In a separate SQL Server that must be provisioned manually"],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages sites are built on top of Microsoft Dataverse, using it as the underlying data store for the information displayed to and captured from site visitors.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-164","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company needs a partner portal where external suppliers register, sign in, and manage their own records. Which Power Platform product is purpose-built for creating such a secure, authenticated external site?","options":["Power Automate desktop flows","Power BI","A canvas app embedded in Microsoft Teams","Power Pages"],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages lets makers build secure, low-code websites for external audiences such as partners and suppliers, including sign-in and self-service management of their data.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-165","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to control which authenticated users can view or edit specific Dataverse tables surfaced on a Power Pages site. Which Power Pages security concept assigns those permissions to groups of users?","options":["Environment security roles in the admin center","Web roles, which link users to table permissions","Azure network security groups","Office 365 licensing groups"],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Power Pages, web roles are assigned to authenticated users and connect them to table permissions, controlling what data those users can access on the site.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-166","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When configuring a new Power Pages site, an administrator sets its visibility to \"private.\" What is the effect of this setting?","options":["The site is fully deleted after a set number of days","The site becomes searchable on public search engines immediately","Only users in the maker's organization (such as team members) can access the site during development","All anonymous internet users can view every page without restriction"],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Site visibility can be set to private so that access is restricted to users within the organization, which is useful while the site is being built before it goes public.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-167","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A marketing team wants anonymous visitors on the public internet to read published articles on a Power Pages site without signing in, while a member area requires login. Which pair of security concepts supports controlling access at the page level for both audiences?","options":["Data loss prevention policies and environment types","Connector consent and premium licensing","Solution layers and managed environments","Page permissions combined with authentication (sign-in) settings"],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages uses page permissions together with authentication to allow anonymous access to some pages while restricting others to signed-in users, matching each audience's needs.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-168","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is a typical use case for Power Pages rather than for an internal Power Apps canvas or model-driven app?","options":["A customer self-service portal where the public can submit support cases and track them","A dashboard used only by the finance department to approve invoices","An employee time-tracking app installed on internal devices","A background automation that syncs two internal systems on a schedule"],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages targets external-facing scenarios such as customer self-service portals, whereas canvas and model-driven apps are typically for internal users, and automation is Power Automate's role.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-169","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to grant a signed-in external user the ability to create and read records in a specific Dataverse table through a Power Pages form. Which Power Pages security element defines that create and read access to the table?","options":["A DLP data policy","A Dataverse business rule","A table permission","An environment maker role"],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Table permissions in Power Pages define the operations (create, read, write, delete) that users can perform on a Dataverse table, and they are granted to users through web roles.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-170","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How does Power Pages render its sites so they display correctly on phones, tablets, and desktops?","options":["Makers must build a separate site for each device size","Visitors must request a mobile version by email","Sites only work in a dedicated mobile app installed by visitors","Sites use responsive design that adapts to different screen sizes automatically"],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages sites render responsively, automatically adjusting their layout to render well across desktops, tablets, and mobile devices.","source":{"title":"Power Pages capabilities — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/capabilities"}},{"id":"gen-171","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants to start a Power Pages site quickly by describing what they need in natural language and having pages generated for them. Which method of creating a site does this describe?","options":["Manually writing HTML and CSS from scratch","Creating the site with Copilot by describing it in natural language","Importing a completed website from an external hosting provider","Exporting a model-driven app as a website"],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages supports creating a site with Copilot, where the maker describes the site in natural language and AI generates pages and data structures to start from.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-172","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Besides starting from Copilot, which additional method can a maker use to create a Power Pages site?","options":["By choosing a prebuilt template as a starting point","By deploying a virtual machine in Azure","By installing a browser extension","By writing a Power Automate desktop flow"],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages provides prebuilt templates that makers can choose as a starting point, in addition to describing a site with Copilot or starting from a blank site.","source":{"title":"Power Pages capabilities — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/capabilities"}},{"id":"gen-173","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A design team wants to know what the Power Pages design studio lets them do without writing code. Which set of tasks is Power Pages designed to support in a low-code way?","options":["Managing physical network hardware and firewalls","Writing and compiling C# backend services","Designing pages, styling the site, managing data, and configuring security through visual workspaces","Administering the tenant's Active Directory forest"],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Pages design studio provides visual workspaces for designing pages, styling, managing data, and setting up security, all through a low-code experience.","source":{"title":"Power Pages capabilities — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/capabilities"}},{"id":"gen-174","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer wants external customers to sign in to its Power Pages site using existing credentials such as a Microsoft or other social/enterprise identity. Which Power Pages capability makes this possible?","options":["Local Windows accounts created on the web server","A shared single password printed on the home page","Anonymous-only access with no sign-in option","Configurable authentication with identity providers"],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages supports authentication through configurable identity providers, letting external users sign in with existing credentials such as Microsoft, other social, or enterprise accounts.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-175","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which description best captures the intended audience of a Power Pages website compared with a standard Power Apps app?","options":["Power Pages is only for internal administrators","Power Pages is aimed at external users and the public, while Power Apps typically serves internal organizational users","Both are exclusively for anonymous internet users","Both can only be accessed from within the Power Platform admin center"],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is designed for external-facing audiences including customers and the public, whereas Power Apps apps are generally intended for internal business users.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-176","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A nonprofit wants to build an event registration website that the general public can browse anonymously but that requires sign-in to complete a registration. Which combination correctly reflects how Power Pages handles these two levels of access?","options":["Anonymous pages are served to the public, while authenticated access with web roles and permissions gates the registration","It cannot support both; the entire site must be either public or private","Every visitor must be added as an environment maker first","Registration requires each visitor to have a paid Power Apps per-user license"],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages can serve some pages anonymously to the public while requiring authentication, web roles, and permissions to access restricted actions such as registration.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-177","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Power Platform service should an organization choose to give thousands of anonymous, unlicensed members of the public a way to interact with its business data through a website?","options":["A model-driven app, which each visitor must be licensed to open","Power Automate cloud flows","Power Pages, which is built for external websites accessible to the public","A canvas app shared individually with each visitor"],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is designed for public-facing websites where large numbers of external users, including anonymous visitors, can interact with an organization's data.","source":{"title":"What is Power Pages? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/introduction"}},{"id":"gen-178","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Power Pages, what is the relationship between web roles and table permissions?","options":["They are unrelated; web roles apply only to page colors","Table permissions define allowed operations on Dataverse tables, and web roles associate users with those permissions","Web roles replace the need for any Dataverse tables","Table permissions are only used for anonymous users and web roles only for admins"],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Table permissions specify what actions can be taken on Dataverse data, and web roles link users to those table permissions to enforce access on the site.","source":{"title":"Power Pages security — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/security/power-pages-security"}},{"id":"gen-179","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker highlights that Power Pages integrates with the broader Power Platform. Which example correctly reflects this integration capability?","options":["A Power Pages site can surface Dataverse data and work alongside Power Apps and Power Automate","A Power Pages site can only display static text files","A Power Pages site requires a completely separate database disconnected from Dataverse","A Power Pages site cannot use any automation or business logic"],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Pages is built on Dataverse and integrates with the rest of the Power Platform, so sites can surface Dataverse data and work with Power Apps and Power Automate.","source":{"title":"Power Pages capabilities — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/capabilities"}},{"id":"gen-180","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker opens Power Pages to build a new external-facing website. Beyond naming the site, what must they choose as part of provisioning it?","options":["A GitHub repository and a branch","A Power BI workspace and dataset","An Azure subscription and resource group","An environment and a site template"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When you create a Power Pages site you select the environment it will live in and a site template as the starting point before the site is provisioned.","source":{"title":"Create a site with Power Pages — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/create-manage"}},{"id":"gen-181","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to quickly generate a starter site—with pages and a backing data table—simply by describing the website they need in plain language. Which capability should they use?","options":["Import a Power Apps canvas app","Write Liquid templates by hand","Create a site with Copilot","Restore a site from a backup"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot for site creation lets a maker describe the site in natural language, and it generates a starter site including pages and a Dataverse table to build on.","source":{"title":"Create a Power Pages site with Copilot — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/create-site-copilot"}},{"id":"gen-182","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Power Pages design studio, which workspace do makers use to add pages, add sections, and place components on the site?","options":["Pages","Data","Styling","Set up"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Pages workspace is where makers add and edit pages, add sections and columns, and insert components to build the site's content.","source":{"title":"Use the design studio — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/use-design-studio"}},{"id":"gen-183","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker needs to change the site's colors and fonts to match corporate branding. Which design studio workspace should they open?","options":["Pages","Styling","Data","Set up"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Styling workspace controls the site's overall look, including themes, color palette, and fonts.","source":{"title":"Use the design studio — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/use-design-studio"}},{"id":"gen-184","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to create and modify the Dataverse tables that store the site's information without leaving the design studio. Which workspace provides this?","options":["Pages","Styling","Set up","Data"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Data workspace lets makers create and edit Dataverse tables and columns used by the site directly inside the design studio.","source":{"title":"Use the design studio — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/use-design-studio"}},{"id":"gen-185","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An administrator needs to manage site details, identity providers, and general site settings. Which design studio workspace is intended for this?","options":["Pages","Styling","Set up","Data"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Set up workspace is used to configure site settings such as site details, authentication and identity providers, and other administration options.","source":{"title":"Use the design studio — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/use-design-studio"}},{"id":"gen-186","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When adding a new page in the Pages workspace, a maker is offered ready-made arrangements of sections and columns to start from. What are these called?","options":["Standard page layouts","Web roles","Business rules","Connectors"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When you add a page you can choose a standard page layout, a prebuilt arrangement of sections and columns, or start from a blank page.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}},{"id":"gen-187","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A Power Pages page is organized into horizontal bands, and makers place components into them to build the page. What are these horizontal bands called?","options":["Environments","Sections","Solutions","Dataflows"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Pages are built from sections—horizontal bands that hold columns and components—which makers add and rearrange to structure the page.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}},{"id":"gen-188","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants site visitors to fill in and submit information that is saved to a Dataverse table. Which component should they add to the page?","options":["A video component","A spacer component","A breadcrumb component","A form component"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A form component is bound to a Dataverse table and lets visitors enter and submit data that is stored in that table.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}},{"id":"gen-189","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to display a read-only, tabular set of records from a Dataverse table on a page. Which component fits this need?","options":["A button component","An image component","A list component","A text component"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A list component shows records from a Dataverse table in a tabular, read-only view on the page.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}},{"id":"gen-190","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Styling workspace, a maker picks from ready-made design options to change the overall look of the whole site in one step. What are these options called?","options":["Preset themes","Web templates","Security roles","Environment variables"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Styling workspace offers preset themes that apply a coordinated set of colors and fonts to instantly change the site's overall appearance.","source":{"title":"Style your Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/style-site"}},{"id":"gen-191","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After applying a preset theme, a maker wants to fine-tune the specific colors used throughout the site. What does the Styling workspace let them adjust?","options":["The data loss prevention policy","The color palette","The table relationships","The flow trigger conditions"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Beyond preset themes, the Styling workspace lets makers customize the color palette and fonts to refine the site's branding.","source":{"title":"Style your Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/style-site"}},{"id":"gen-192","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"While working inside the design studio, a maker types a description asking to add a new page containing a contact form. Which feature interprets this request and generates the page?","options":["Power Fx delegation","A desktop flow","The solution checker","Copilot in Power Pages"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Copilot in Power Pages can create and modify pages and content from natural-language descriptions typed by the maker in the design studio.","source":{"title":"Create a Power Pages site with Copilot — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/create-site-copilot"}},{"id":"gen-193","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before making the site available to visitors, a maker wants to see how it will appear to end users. Which design studio capability should they use?","options":["Publish straight to production","Export a managed solution","Preview the site","Run process mining"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The design studio provides a preview option so makers can see how the site renders to visitors, including on different screen sizes, before it goes live.","source":{"title":"Use the design studio — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/use-design-studio"}},{"id":"gen-194","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A newly provisioned Power Pages site is initially restricted so only makers can see it. What must be done so the intended audience can reach it on the internet?","options":["Make the site go live by changing its visibility","Delete the default environment","Install an on-premises data gateway","Assign each visitor a Power BI Pro license"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A new site starts private; the maker makes it go live, changing its visibility so the target audience can access it publicly.","source":{"title":"Create a site with Power Pages — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/create-manage"}},{"id":"gen-195","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to add a heading and a paragraph of marketing copy to the home page and edit the wording directly on the canvas. Which component should they add?","options":["A form component","A text component","A list component","An iframe component"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A text component lets makers add and edit headings and paragraph content inline using a rich-text editor on the page.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}},{"id":"gen-196","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When creating a site, Power Pages offers prebuilt starting points designed for specific scenarios so makers don't begin from a blank site. What are these called?","options":["Cloud flow templates","Report themes","Site templates","Data policies"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Site templates are prebuilt starting points for common scenarios that makers can choose when creating a site instead of starting blank.","source":{"title":"Create a site with Power Pages — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/create-manage"}},{"id":"gen-197","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker adds a new page and wants it to appear in the site's navigation menu. In which design studio workspace are pages and their placement in navigation managed?","options":["Styling","Data","Set up","Pages"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Pages workspace is where makers add pages and control their arrangement, including whether a page appears in the site's navigation.","source":{"title":"Create your first Power Pages site — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-pages/getting-started/first-page"}}];
